WITH payload AS (SELECT $archive_payload$[{"id":"a7227a5e-2e0d-5bfb-8981-c8428eee1133","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب بقصد الترويج -قات -املدعى عليه أجنبي - نص التعميم القضائي على عدم إطالة سجن االجنبي -التعزير بالسجن واجللد والغرامة واالبعاد.","document_number":"34292073","case_number":"34352362","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/8","year":"1434","subject":"مخدرات -تهريب بقصد الترويج -قات -املدعى عليه أجنبي - نص التعميم القضائي على عدم إطالة سجن االجنبي -التعزير بالسجن واجللد والغرامة واالبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34292073 :‬تاريخه ‪1434/8/8 :‬هـ‬\n                  ‫رقم الدعوى‪34352362 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34317014‬تاريخه‪1434/9/10 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬تهريــب بقصــد الترويــج ‪ -‬قــات ‪ -‬املدعــى عليــه أجنبــي ‪-‬‬\n‫نــص التعميــم القضائــي علــى عــدم إطالــة ســجن االجنبــي‪ -‬التعزيــر‬\n                                  ‫بالســجن واجللــد والغرامــة واالبعــاد‪.‬‬\n\n\n\n\n                ‫‪ -1‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪1432/12/9‬هـ‪.‬‬\n                       ‫‪ -2‬قرار مجلس الوزراء رقم (‪ )11‬يف ‪1374/2/1‬هــ‪.‬‬\n‫‪ -3‬الفقــرة (أ) مــن املــادة األولــى مــن قــرار ســمو وزيــر الداخليــة رقــم‬\n                                                ‫(‪ )2057‬يف ‪1404/5/26‬ه ـ‪.‬ـ‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتهريــب قــات مــن اليمــن إلــى‬\n‫الســعودية بقصــد الترويــج ‪ -‬طلــب إثبــات مــا أســند إليــه ومعاقبتــه‬\n‫تعزيــر ًا وإبعــاده عــن البــاد‪ ،‬حيــث مت القبــض علــى املدعــى عليــه بعــد‬\n‫دخولــه األراضــي الســعودية ســير ًا علــى األقــدام بطريقــة غيــر مشــروعة‬\n‫وبحوزتــه نبــات القــات واعتــرف املدعــى عليــه وصــادق علــى الدعــوى‪،‬‬\n‫إثبــات إدانــة املدعــى عليــه بتهريــب القــات بقصــد الترويــج‪ ،‬وبنــاء علــى‬\n‫مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن ســنة واالســتعاضة عــن‬\n‫تخفيــف الســجن بكثــرة اجللــد بخمســمائة جلــدة مفرقــة علــى دفعــات‬\n                                                                                   ‫‪126‬‬\n\f      ‫مقــدار كل دفعــة خمســون جلــدة لكونــه وافــد ســيرحل عــن البــاد‬\n      ‫وال فائــدة ترجــى مــن إطالــة ســجنه ولعــدم وجــود ســوابق عليــه ولقلــة‬\n      ‫ا بتعليمــات ولــي األمــر التــي تقضــي بتخفيــف‬     ‫الكميــة املهربــة وعم ـ ً‬\n      ‫ســجن الوافديــن واالســتعاضة بكثــرة اجللــد وغرامــة ماليــة قدرهــا‬\n      ‫خمســة آالف ريــال تــودع يف بيــت مــال املســلمني وإبعــاده عــن البــاد بعــد‬\n      ‫إنفــاذ العقوبــة وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون الئحــة‪،‬‬\n                                      ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬       ‫ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34352362‬وتاريــخ ‪1434/07/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341832181‬وتاريــخ ‪1434/07/29‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق ‪1434/7/30‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 30‬وفيهــا‬\n      ‫حضــر املدعــي العــام ‪ .....‬بالتعميد رقــم(‪ ).....‬يف ‪1431/8/13‬هـ واملدعى‬\n      ‫عليــه ‪.....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬وقــدم املدعي‬\n      ‫العــام دعــوى محــررة تتضمــن‪ :‬إنــه بتاريــخ ‪1434/5/11‬ه ـ ألقــت إحــدى‬\n      ‫دوريــات حــرس احلــدود باحلــرث القبــض علــى املدعــى عليــه املذكــور‬\n      ‫أعــاه بعــد دخولــه األراضــي الســعودية قادم ًا من األراضي اليمنية ســير ًا‬\n      ‫علــى األقــدام بطريقــة غيــر مشــروعة وبحوزتــه كميــة مــن نبــات القــات‬\n      ‫احملظــور بلــغ وزنهــا (‪16‬كجــم) ســتة عشــر كيلــو جــرام وكان يرافقــه‬\n      ‫احلــدث‪( ..... /‬جــرى ترحيلــه لبــاده لكونــه مصــاب مبــرض اجلــرب)‬\n      ‫وأثبــت التقريــر الكيميائــي الشــرعي رقــم(‪ ).....‬وتاريــخ ‪1434/6/7‬ه ـ‬\n\n‫‪127‬‬\n\f‫ايجابيــة العينــة املرســلة منهــا لنبــات القــات احملظــور وصــدر بحــق املتهــم‬\n‫املذكــور القــرار اإلداري رقــم (‪ ).....‬وتاريــخ ‪1434/6/20‬ه ـ مــن قبــل‬\n‫حــرس احلــدود القاضــي بســجنه ملــدة (‪ 4‬شــهور) وباســتجواب املدعــى‬\n‫عليــه املذكــور ومواجهتــه بالتهمــة املنســوبة إليــه أقــر بصحــة واقعــة‬\n‫القبــض وبتهريبــه كميــة نبــات القــات احملظــور املضبوطــة معــه بلــغ‬\n‫وزنهــا (‪16‬كجــم) ســتة عشــر كيلــو جــرام وأنــه مؤجــر علــى حملهــا‬\n‫مــن شــخص مينــي باليمــن يدعى‪.....‬مببلــغ (‪ )125‬مائــة وخمســة وعشــرين‬\n‫ريــال ســعودي ويرغــب يف ايصالهــا للســعودية وحتديــد ًا للشــبك احلــدودي‬\n‫ويســتلمها منــه املدعــو ‪.....‬مينــي اجلنســية ويقــوم بايصالهــا لقريــة ‪ .....‬وقــد‬\n‫صــادق علــى أقوالــه حتقيقـ ًا وقــد أســفر التحقيــق مــع املدعــى عليــه عــن‬\n‫توجيــه االتهــام لــه بارتكابــه جرميــة تهريــب مــا وزنــه ســتة عشــر كيلــو‬\n‫جــرام مــن نبــات القــات احملظــور من اليمن إلى الســعودية بقصد الترويج‬\n‫املجــرم مبوجــب الفقــرة (‪ )1‬مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪39/‬‬\n‫يف ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا ورد بأقــوال‬\n‫املتهــم مــن اعتــراف املدونــة بدفتــر التحقيــق املرفــق لفــة (‪ -2 )20‬مــا‬\n‫ورد مبحضــر القبــض والتفتيــش املرفــق لفــة (‪ -3 )3‬مــا ورد يف التقريــر‬\n‫الكيميائــي املرفــق بــاألوراق لفــة (‪ )17‬وبالبحــث عــن ســوابقه لــم يعثــر‬\n‫لــه علــى ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم‬\n‫شــرع ًا ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ وماحلــق بــه مــن تعديــات لــذا أطلــب‪1 :‬ـ إثبــات إدانتــه مبــا‬\n‫أســند إليــه واحلكــم بتعزيــره يف ضــوء املــادة (األولى) من القــرار الوزاري‬\n‫املشــار إليــه أعــاه إنفــاذا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n\n\n                                                                                         ‫‪128‬‬\n\f      ‫‪1432/12/9‬ه ـ ‪2‬ـ احلكــم بإبعــاده لبــاده اســتناد ًا للمــادة املذكــورة‬\n      ‫وبســؤال املدعــى عليــه ‪.....‬مينــي اجلنســية أجــاب باالعتــراف بتهريــب مــا‬\n      ‫وزنــه ســتة عشــر كيلــو جرامـ ًا مــن نبــات القــات احملظــور مــن األراضــي‬\n      ‫اليمنيــة إلــى األراضــي الســعودية حلســاب الغيــر مقابل مبلــغ مالي هكذا‬\n      ‫أجــاب عنــد ذلــك جــرى منــا االطــاع علــى التقرير الكيميائي الشــرعي‬\n      ‫وعلــى محضــري الــوزن والقبــض فوجــدت متطابقــة ملــا جــاء بالدعــوى‬\n      ‫وبنــاء علــى مــا ذكــر مــن دعــوى املدعــي العــام وعلــى إجابــة املدعــى‬\n      ‫عليــه ‪.....‬مينــي اجلنســية باالعتــراف بتهريــب مــا وزنــه ســتة عشــر كيلــو‬\n      ‫جرام ـ ًا مــن نبــات القــات احملظــور مــن األراضــي اليمنيــة إلــى األراضــي‬\n      ‫الســعودية حلســاب الغيــر مقابــل مبلــغ مالــي لــذا فقــد ثبــت لــدي شــرع ًا‬\n      ‫إدانــة املدعــى عليــه املذكــور بتهريــب كميــة نبــات القــات احملظــور‬\n      ‫املوضحــة أعــاه مــن األراضــي اليمنيــة إلــى األراضــي الســعودية حلســاب‬\n      ‫الغيــر مقابــل مبلــغ مالــي لقصــد الترويــج وهــو يســتحق العقوبــة علــى ذلك‬\n      ‫وفــق الفقــرة (أ) مــن املــادة األولــى مــن قــرار ســمو وزيــر الداخليــة رقــم‬\n      ‫(‪ )2057‬وتاريــخ ‪1404 /5/26‬ه ـ اســتناد ًا لقــرار مجلــس الــوزراء رقــم‬\n      ‫(‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ وإنفــاذ ًا لألمــر الســامي رقــم (‪ )59633‬يف‬\n      ‫‪1432/12/9‬ه ـ وملــا ذكــر أعــاه ولكــون املدعــى عليــه وافــد ًا ســيرحل‬\n      ‫عــن البــاد وال فائــدة ترجــى مــن إطالــة ســجنه ولعــدم وجــود ســوابق‬\n      ‫ا مبقتضــى تعليمــات ولــي‬   ‫عليــه ولقلــة كميــة نبــات القــات املهربــة وعمـ ً‬\n      ‫األمــر التــي تقضــي بتخفيــف ســجن الوافديــن واالســتعاضة عنــه بكثــرة‬\n      ‫اجللــد لــذا فقــد حكمــت بتعزيــره بالســجن ملــدة ســنة مــن تاريــخ إيقافــه‬\n      ‫علــى ذمــة القضيــة يف ‪1434/5/11‬ه ـ وجلــده بخمســمائة جلــدة علن ـ ًا‬\n      ‫مفرقــة كل دفعــة خمســون جلــدة بــن الدفعــة واألخــرى عشــرة أيــام‬\n\n\n‫‪129‬‬\n\f‫وغرامــة ماليــة قدرهــا خمســة آالف ريــال تــودع بيــت مــال املســلمني‬\n‫ويبعــد عــن البــاد بعــد إنفــاذ العقوبــة املقــررة بحقــه شــرع ًا وال يســمح‬\n‫لــه بالدخــول إليهــا عــدى مــا تســمح بــه تعليمــات احلــج والعمــرة هــذا مــا‬\n‫حكمــت بــه وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة وطلــب‬\n‫املدعــي العــام اســتئناف احلكــم مكتفيـ ًا بالئحــة اإلدعــاء العــام وأمــرت‬\n‫بتنظيــم القــرار الــازم مبوجبــه ورفعــه حملكمــة اإلســتئناف مبنطقــة‬\n‫عســير لدراســته وإبــداء مــا تــراه نحــوه وصلــى اهلل علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/7/30‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n‫‪ 341832181‬وتاريــخ ‪1434/8/14‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقم ‪34292073‬‬\n‫وتاريــخ ‪1434/8/8‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ (..... /‬مينــي‬\n‫اجلنســية ) يف قضيــة ( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n                     ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":126,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e6d84fdfae797e5dc92d2b4a4c87f3b5a6ebed0c6e1883036f87e4f6807833db","normalized_text_hash":"d0ea5ecd7bdfbdf5a9cf7e55ef47cb2f8345175c45b3c5c077d86ba3094a22bb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p126-34292073"},{"id":"b2f1715b-ba1b-59c7-925d-9006454a2320","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب القات بقصد الترويج -قات -الهرب من رجال األمن -اإلقرار -اإلدانة -تداخل العقوبات التعزيرية -تعزير بالسجن والغرامة واإلتاف واملصادرة واإلبعاد -ما قرره أهل العلم يف تداخل العقوبات التعزيرية قال العالمة البهوتي (ولو توجه عليه تعزيرات على معاص شتى فإن متحضت هلل تعالى واحتد نوعها كأن قبل أجنبية مرار ا أو اختلف نوعها بأن قبل أجنبية وملس أخرى قصد ا تداخلت وكفاه تعزير واحد)","document_number":"34312859","case_number":"34404506","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/6","year":"1434","subject":"مخدرات -تهريب القات بقصد الترويج -قات -الهرب من رجال األمن -اإلقرار -اإلدانة -تداخل العقوبات التعزيرية -تعزير بالسجن والغرامة واإلتاف واملصادرة واإلبعاد -ما قرره أهل العلم يف تداخل العقوبات التعزيرية قال العالمة البهوتي (ولو توجه عليه تعزيرات على معاص شتى فإن متحضت هلل تعالى واحتد نوعها كأن قبل أجنبية مرار ا أو اختلف نوعها بأن قبل أجنبية وملس أخرى قصد ا تداخلت وكفاه تعزير واحد)","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34312859 :‬تاريخه‪1434/9/6:‬هـ‬\n                        ‫رقم الدعوى‪34404506 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34366949‬تاريخه‪1434/11/12 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬تهريــب القــات بقصــد الترويــج ‪ -‬قــات ‪ -‬الهــرب مــن رجــال‬\n      ‫األمــن ‪ -‬اإلقــرار ‪-‬اإلدانــة‪ -‬تداخــل العقوبــات التعزيريــة‪ -‬تعزيــر‬\n                          ‫بالســجن والغرامــة واإلتــاف واملصــادرة واإلبعــاد‬\n\n\n\n\n      ‫‪ -‬مــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة قــال العالمــة‬\n      ‫البهوتــي (ولــو توجــه عليــه تعزيــرات علــى معــاص شــتى فــإن متحضــت‬\n      ‫هلل تعالــى واحتــد نوعهــا كأن قبــل أجنبيــة مــرار ًا أو اختلــف نوعهــا‬\n      ‫بــأن قبــل أجنبيــة وملــس أخــرى قصــد ًا تداخلــت وكفــاه تعزيــر واحــد)‬\n                                 ‫كشــاف القنــاع عــن مــن اإلقنــاع ((‪.)485/20‬‬\n      ‫‪ -‬مــا تضمنــه األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ‬\n      ‫يف فقرتــه األولــى مــن املوافقــة علــى أن تطبــق احملاكــم علــى مرتكبــي‬\n      ‫جرائــم القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام مكافحــة‬\n                                                   ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n                     ‫‪ -‬املادة (‪)1‬من قرار مجلس الوزراء رقم (‪ )11‬عام ‪1374‬هـ‬\n      ‫‪ -‬الفقــرة (أ) مــن املــادة األولــى مــن قــرار ســمو وزيــر الداخليــة رقــم‬\n                                                          ‫(‪ )2057‬وتاريــخ ‪1404‬ه ـ‬\n\n\n\n\n‫‪131‬‬\n\f‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتهريــب مــا وزنــه اثنــا عشــر‬\n‫كيلــو جــرام مــن نبــات القــات احملظــور بقصــد االجتــار وتهريبــه‬\n‫القــات احملظــور يف الســابق ومحاولــة هروبــه مــن رجــال األمــن وطلــب‬\n‫املدعــي العــام إثبــات إدانــة املدعــى عليــه مبــا أســند إليــه واحلكــم عليــه‬\n‫بعقوبــة تعزيريــة‪ ،‬والتشــديد عليــه لقــاء تعــدد ســوابقه‪ ،‬وإبعــاده عــن‬\n‫البــاد بعــد انتهــاء محكوميتــه وتعزيــره لقــاء تهريبــه القــات يف الســابق‬\n‫ومحاولــة هروبــه مــن رجــال األمــن وبعــرض دعــوى املدعــي العــام علــى‬\n‫املدعــى عليــه صــادق علــى القبــض عليــه أثنــاء تهريبــه لكميــة القــات‬\n‫املذكــورة وهربــه مــن رجــال األمــن كمــا صــادق علــى الســوابق املســجلة‬\n‫عليــه وتهريبــه لنبــات القــات يف الســابق ‪،‬وملــا كان مــا تقــدم حكمــت‬\n‫احملكمــة بالســجن مــدة ثــاث ســنوات وتغرميــه مبلــغ خمســة آالف‬\n‫ريــال يــؤول إلــى اخلزينــة العامــة للدولــة وإبعــاده إلــى بــاده بعــد انتهــاء‬\n‫محكوميتــه بالســجن ومصــادرة وإتــاف كميــة القــات املضبوطــة‬\n‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام معارضتــه وطلــب‬\n‫رفعــه حملكمــة االســتئناف دون الئحــة فأجيــب لذلــك وقــرر املدعــى‬\n          ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬         ‫عليــه القناعــة بــه‪ُ ،‬‬\n\n\n\n\n                                                                                        ‫‪132‬‬\n\f      ‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪ ......‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n      ‫واملقيــدة بــوارد احملكمــة برقــم (‪ )342083455‬وتاريــخ ‪1434/8/29‬هـ‬\n      ‫واحملالة من فضيلة الرئيس برقم (‪ )34404506‬وتاريخ ‪1434/8/29‬هـ‬\n      ‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪ ......‬املتهــم يف قضيــة قــات عليــه‬\n      ‫ففــي هــذا اليــوم اخلميــس ‪1434/9/2‬ه ـ افتتحــت اجللســة األولــى يف‬\n      ‫متــام الســاعة الواحــدة والنصــف وفيهــا حضــر املدعــي العــام ‪ ......‬املوجــه‬\n      ‫باخلطــاب رقــم (‪ ) ......‬وتاريــخ ‪1434/8/29‬ه ـ وادعــى علــى احلاضــر‬\n      ‫‪ ...... ......‬مينــي اجلنســية يحمــل البطاقــة البديلــة رقــم (‪ ) ......‬صــادرة‬\n      ‫مــن حــرس احلــدود بتاريــخ ‪1434/5/27‬ه ـ أنــه بتاريــخ ‪1434/5/27‬ه ـ‬\n      ‫وأثنــاء قيــام إحــدى دوريــات حــرس احلــدود بواجبهــا شــوهدت مجموعــة‬\n      ‫مــن األشــخاص أثنــاء قدومهــم مــن األراضــي اليمنيــة إلــى األراضــي‬\n      ‫الســعودية ســير ًا علــى األقــدام بطريقــة غيــر مشــروعة فتــم اعتراضهــم‬\n      ‫وطلــب الوقــوف إال أنهــم قامــوا بالهــرب فتــم إطــاق النــار عليهــم ممــا‬\n      ‫أدى إلــى إصابــة املدعــى عليــه وضبطــت بحوزتــه كميــة مــن نبــات القــات‬\n      ‫احملظــور بلــغ وزنهــا (‪12‬كجــم) اثنــي عشــر كيلــو جــرام ويقــع مــكان‬\n      ‫القبــض علــى خــط قريــة اخلشــل وأثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم‪ ......‬وتاريــخ ‪1434/7/2‬ه ـ الصــادر مــن قســم الســموم والكيميــاء‬\n      ‫الشــرعية بجــازان إيجابيــة العينــات املرســلة منــه لنبــات القــات احملظــور‬\n      ‫املــدرج باجلــدول رقــم (‪ )2‬فئــة (أ‪،‬ج) واجلــدول رقــم (‪ )4‬امللحقــن بنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n\n‫‪133‬‬\n\f‫م‪ 39/‬يف ‪1426/7/8‬ه ـ وصــدر بحقــه قــرار اللجنــة اإلداريــة بحــرس‬\n‫احلــدود رقــم (‪ ) ......‬وتاريخ‪1434/7/10‬ه ـ بســجنه مــدة أربعــة أشــهر‬\n‫ملخالفتــه للمــادة (‪ )15‬مــن نظــام أمــن احلــدود وباســتجواب املدعــى عليــه‬\n‫املذكــور أعــاه إليــه أقــر بتهريــب الكميــة املضبوطــة بحوزتــه مــن نبات‬\n‫القــات احملظــور مــن اليمــن إلــى الســعودية لغــرض إيصالهــا إلــى شــبك‬\n‫احلــدود الســعودية وســيقوم شــخص ال يعرفــه باســتالمها وذلــك مقابــل‬\n‫أجــر مــادي قــدره خمســون ريــا ًال وصــادق علــى أقوالــه بذلــك حتقيق ـ ًا‬\n‫ومت إيقافــه اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ‬\n‫املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة وبالبحــث عــن‬\n‫ســوابقه عثــر لــه علــى ســابقة يف تهريــب القــات وأخــرى يف حيازته بقصد‬\n‫االســتعمال الشــخصي مقترنــة بدخــول األراضــي الســعودية أو اخلــروج‬\n‫منهــا بطريقــة غيــر نظاميــة وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n‫للمدعــى عليــه بتهريــب مــا وزنــه (‪12‬كجــم) اثنــي عشــر كيلــو جــرام‬\n‫مــن نبــات القــات احملظــور بقصــد االجتــار وتهريبــه القــات احملظــور يف‬\n‫الســابق ومحاولــة هروبــه مــن رجــال األمــن وألن مــا أقــدم عليــه املدعــى‬\n‫عليــه املذكــور فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب قــرار‬\n‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات فقــد‬\n‫طلــب املدعــي العــام إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره يف‬\n‫ضــوء املــادة األولــى مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذ ًا لألمــر‬\n‫الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ والتشــديد‬\n‫عليــه لقــاء تعــدد ســوابقه وإبعــاده عــن البــاد بعــد انتهــاء محكوميتــه‬\n‫اســتنادا للمــادة أعــاه وتعزيــره لقــاء تهريبــه القــات يف الســابق ومحاولــة‬\n‫هروبــه مــن رجــال األمــن وبعــرض دعــوى املدعــي العــام علــى املدعــى‬\n\n\n                                                                                            ‫‪134‬‬\n\f      ‫عليــه صــدق القبــض عليــه يف الزمــان واملــكان املذكوريــن أعــاه‬\n      ‫أثنــاء تهريبــه لكميــة القــات املشــار إليهــا يف الدعــوى وهربــه مــن رجــال‬\n      ‫األمــن كمــا صــدق الســوابق املســجلة عليــه وتهريبــه لنبــات القــات يف‬\n      ‫الســابق هكــذا أجــاب وبالرجــوع إلــى أوراق املع ــاملة جــرى االطــاع‬\n      ‫علــى التقريــر الكيميائــي الشــرعي وثبــت ســوابق املدعــى عليــه‬\n      ‫وقــرار اللجنــة اإلداريــة بحــرس احلــدود املرفــق علــى اللفــة رقــم (‪)22‬‬\n      ‫فوجــدت مطابقــة ملــا يف الدعــوى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وملــا تضمنــه األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n      ‫‪1432/12/9‬ه ـ يف فقرتــه األولــى مــن املوافقــة علــى أن تطبــق احملاكــم‬\n      ‫علــى مرتكبــي جرائــم القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة لذلــك كلــه فقــد قــررت مــا‬\n      ‫يلــي أوال ثبتــت لــدي إدانــة املدعــى عليــه بالهــرب مــن رجــال األمــن وهــو‬\n      ‫يســتحق العقوبــة التعزيريــة لقــاء ذلــك ثانيــا ثبتــت لــدي إدانــة املدعــى‬\n      ‫عليــه بتهريــب نبــات القــات يف الســابق وهــو يســتحق العقوبــة التعزيريــة‬\n      ‫لقــاء ذلــك ثالثــا ثبتــت لــدي إدانــة املدعــى عليــه بتهريــب كميــة القــات‬\n      ‫املذكــورة أعــاه بقصــد االجتــار والترويــج وهــو يســتحق العقوبــة علــى‬\n      ‫ذلــك وفــق املــادة (‪ )1‬مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬عــام ‪1374‬ه ـ‬\n      ‫والفقــرة (أ) مــن املــادة األولــى من قرار ســمو وزيــر الداخلية رقم (‪)2057‬‬\n      ‫وتاريخ‪1404/5/26‬ه ـ ه ـ وملــا قــرره أهــل العلــم يف تداخــل العقوبــات‬\n      ‫التعزيريــة قــال العالمــة البهوتــي (ولــو توجــه عليــه تعزيــرات علــى معــاص‬\n      ‫شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل أجنبيــة مــرار ًا أو‬\n      ‫اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــد ًا تداخلــت وكفــاه‬\n      ‫تعزيــر واحــد) كشــاف القنــاع عــن مــن اإلقنــاع (ج‪20‬ص‪ )485‬لذلــك‬\n\n\n‫‪135‬‬\n\f‫كلــه فقــد قــررت االكتفــاء مبجــازاة املدعــى عليــه لقــاء تهريبــه لكمية‬\n‫القــات املضبوطــة ولكــون املضبــوط مــن نبات القات واســتصالحا حلاله‬\n‫فقــد حكمــت عليــه لذلــك بالســجن مــدة ثــاث ســنوات تبــدأ مــن تاريــخ‬\n‫انتهــاء محكوميتــه مــن حــرس احلــدود يف ‪1434/9/26‬ه ـ وتغرميــه مبلــغ‬\n‫خمســة آالف ريــال يــؤول إلــى اخلزينــة العامــة للدولــة وإبعــاده إلــى بــاده‬\n‫بعــد انتهــاء محكوميتــه بالســجن ومصــادرة وإتــاف كميــة القــات‬\n‫املضبوطــة هــذا مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى الطرفــن‬\n‫قــرر املدعــي العــام معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون‬\n‫الئحــة فأجبتــه لذلــك وقــرر املدعــى عليــه القناعــة بــه وقــد جــرى النطــق‬\n‫بــه يف متــام الســاعة الثانيــة إال ربعــا وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n         ‫علــى نبينــا محمــد وآلــه وصحبــه أجمعــن حــرر يف ‪1434/9/2‬ه‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n‫‪ 342083455‬وتاريــخ ‪1434/9/9‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ...... /‬برقــم ‪ 34312859‬وتاريــخ‬\n‫‪1434/9/6‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ( ...... /‬مينــي اجلنســية‬\n‫) يف قضيــة (قــات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪136‬‬\n\f137\n\f138\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":131,"source_page_end":138,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5cede6c7cb602da357ce0617f4bfa1a8452d89d8083515273488e4b994b8e4e1","normalized_text_hash":"0d9c769725866217100c062dd8eec563ba9edfd1fac885124651f3cf48ccfdc0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p131-34312859"},{"id":"2aa4f1d0-842c-5996-b9b5-357a3ce48223","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - حتقيقا بالتعاطي وأنكر حيازة احلشيش املخدر -إقرار املدعى عليه الترويج -وجود سابقة قضائية من جنس اجلناية -عدم ثبوت إدانة -احلكم تعزيرا للقرائن والتهم -التعزير بالسجن واجللد.","document_number":"34209535","case_number":"5896","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام خلف فضيلة القضاة","circuit":"الدائرة الثانية لتمييز القضايا اخلماسية مبحكمة الاستئناف","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/8","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - حتقيقا بالتعاطي وأنكر حيازة احلشيش املخدر -إقرار املدعى عليه الترويج -وجود سابقة قضائية من جنس اجلناية -عدم ثبوت إدانة -احلكم تعزيرا للقرائن والتهم -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34209535 :‬تاريخه ‪1434/5/8 :‬هـ‬\n                             ‫رقم الدعوى ‪5896 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34288017‬تاريخه‪1434/08/3 :‬هـ‬\n\n\n      ‫مخــدرات‪ -‬ترويــج احلشــيش املخــدر ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n      ‫حتقيقــا بالتعاطي وأنكر‬\n                          ‫ً‬     ‫حيــازة احلشــيش املخــدر ‪ -‬إقــرار املدعــى عليــه‬\n      ‫الترويــج ‪ -‬وجــود ســابقة قضائيــة مــن جنــس اجلنايــة ‪ -‬عــدم ثبــوت‬\n      ‫إدانــة ‪ -‬احلكــم تعزيــرا للقرائــن والتهــم ‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫(أول) مــن املــادة (‪ )37‬مــن نظــام مكافحــة‬\n                                                 ‫الفقــرة (‪ )5‬مــن البنــد ً‬\n                                              ‫املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج احلشــيش املخــدر ‪،‬‬\n      ‫مت القبــض علــى املدعــى عليــه وهــو يســلم قطعــة احلشــيش للمصــدر‬\n      ‫الســري يف شــقته‪ ،‬وأثبــت التقريــر إيجابيــة العينــة ملــادة احلشــيش‪،‬‬\n      ‫أقــر املدعــى عليــه أمــام الفرقــة القابضــة بقيامــه بالترويــج ثــم أنكــر‬\n      ‫أمــام القاضــي صفــة الترويــج وأقــر بتعاطــي احلشــيش‪ ،‬طلــب املدعــي‬\n      ‫العــام باحلكــم علــى املدعــى عليــه بعقوبــة القتــل التعزيريــة املنصــوص‬\n      ‫ومصــادرة جوالــه والشــريحة الســتخدامه يف ارتــكاب اجلرميــة وعــدم‬\n      ‫صرفهــا لنفــس املتهــم‪ ،‬حكمــت احملكمــة باإلجمــاع عــدم ثبــوت إدانــة‬\n      ‫املدعــى عليــه بترويــج احلشــيش وال بحيازتــه ‪ ،‬وقــررت احلكــم علــى‬\n\n‫‪139‬‬\n\f‫املدعــى عليــه بالســجن أربــع ســنوات ابتــداء مــن تاريــخ توقيفــه تعزيــرا‬\n‫للقرائــن والتهــم‪ ،‬وجلــده خمســمائة جلــدة مفرقــة علــى عشــر دفعــات‬\n‫كل دفعــة خمســون جلــدة لقــاء الشــبهة القويــة بحقــه بالترويــج‪ ،‬قــرر‬\n‫املدعــى عليــه عــدم قناعتــه باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن قبــل‬\n                                                       ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪ ............‬القضــاة يف احملكمــة العامة‬\n‫بالدمــام خلــف فضيلــة القضــاة‪ .........‬ناظــري القضيــة ســابق ًا بنــاء علــى‬\n‫املعاملــة احملالــة لســلفنا مــن فضيلــة رئيــس احملكمةالعامــة بالدمــام‬\n‫برقــم ‪ ...........‬وتاريــخ ‪ ............‬واملرفــق بهــا القــرار الصــادر مــن قضــاة‬\n‫الدائــرة الثانيــة لتمييــز القضايــا اخلماســية مبحكمــة االســتئناف‬\n‫بالريــاض برقــم ‪ .........‬وتاريــخ ‪ ......‬ونــص املقصــود منــه ‪ :‬نقــرر أن يحــل‬\n‫خلــف أصحــاب الفضيلــة املرقــن واملنقولــن محلهــم يف نظــر القضيــة‬\n‫مــن جديــد ‪.‬ا‪.‬هــ‪ .‬واملرفــق بهــا الئحــة الدعــوى العامــة املقدمــة مــن املدعــي‬\n‫العــام بالدمــام واملتضمنــة ‪ :‬احلمــد هلل وحــده والصــاة والســام علــى مــن‬\n‫ال نبــي بعــده بصفتــي مدعيـ ًا بدائــرة االدعــاء العــام لفرع الهيئة بالشــرقية‬\n‫ادعــي علــى املذكــور أعــاه ‪ ........‬ســعودي اجلنســية بالســجل رقــم ‪..........‬‬\n‫موقــوف مــن تاريــخ ‪ .........‬بشــعبة إصالحيــة الدمــام بتهمــة بيــع املــواد‬\n‫املخــدرة وتعاطــي املــواد املخــدرة وحيــازة مــواد مخــدرة بقصــد التعاطــي‬\n‫واالســتعمال وعليــه ســابقة بيــع املــواد املخــدرة وســابقة ترويــج املخــدرات‬\n‫حيــث أنــه باالطــاع علــى محاضــر البــاغ واالنتقــال والقبــض والتفتيــش‬\n‫املعــدة مــن قبــل رجــال الضبــط اجلنائــي بشــعبة مكافحــة املخــدرات‬\n\n                                                                                         ‫‪140‬‬\n\f      ‫ـاء علــى‬\n              ‫بالدمــام تبــن أ ّنــه يف يــوم الثالثــاء املوافــق ‪1430/6/30‬ه ـ وبنـ ً‬\n      ‫إخباريــة مــن أحــد املصــادر الســرية مفادهــا قيــام املدعــى عليــه بترويــج‬\n      ‫مــادة احلشــيش املخــدر ويســكن حــي ‪ ........‬بالدمــام عليــه مت االنتقــال‬\n      ‫إلــى املوقــع املذكــور ومقابلــة املصــدر وجــرى متكينــه مــن االتصــال علــى‬\n      ‫جــوال املدعــى عليــه ذي الرقــم ‪ ........‬وطلــب منــه قطعــة حشــيش مخــدر‬\n      ‫مببلــغ خمســمائة ريــال وان يحضرهــا لشــقته فوافــق املدعــى عليــه وقــال‬\n      ‫ســوف احضــر إليــك بعــد صــاة املغــرب ومعــي الغــرض وهنــاك قامــت‬\n      ‫ـاء ولــم‬\n             ‫الفرقــة باالنتظــار بشــقة املصــدر حتــى الســاعة التاســعة مسـ ً‬\n      ‫يحضــر فـت ــم االتصــال عليــه مــرة أخــرى من قبــل املصدر فأخبــره املدعى‬\n      ‫عليــه بأنــه لــم يجــد قطعــة بخمســمائة ريــال وال يوجــد ســوى قطعــة مببلــغ‬\n      ‫‪250‬ريــال فطلــب منــه املصــدر إحضارهــا فــرد عليــه املدعــى عليــه بأنــه‬\n      ‫ســوف يحضرهــا بعــد نصــف ســاعة وأخــذ مياطــل حتــى الســاعة احلاديــة‬\n      ‫ـاء وكان شــديد احلــذر ويف آخــر اتصــال لــه باملصــدر كان‬        ‫عشــر مسـ ً‬\n      ‫يســأله هــل عنــدك أحــد فــرد عليــه املصــدر مــا عنــدي أحــد فطلــب مــن‬\n      ‫املصــدر فتــح البــاب ودخــل أعضــاء الفرقــة إحــدى الغــرف ودخــل املدعــى‬\n      ‫عليــه بالصالــة وقابــل املصــدر ثــم خــرج إلحضــار احلشــيش وكان‬\n      ‫حضــوره للشــقة لالطمئنــان وبعــد ربــع ســاعة اتصــل باملصــدر وأخبــره‬\n      ‫بأنــه ســوف يحضــر معــه أحــد أصدقائــه وبعــد حضورهمــا دخــا بإحــدى‬\n      ‫الغــرف وأخــذ املبلــغ املرقــم منهــم وســلم لهــم قطعــة اتضــح يف مــا بعــد‬\n      ‫أنهــا تــزن إحــدى عشــر جرام ـ ًا وتســعة إعشــار اجلــرام اثبــت التقريــر‬\n      ‫الكيمــاوي الشــرعي رقــم ‪ ......‬وتاريــخ ‪1430/7/7‬ه ـ ايجابيــة عينتهمــا‬\n      ‫ملــادة احلشــيش املخــدر املــدرج يف اجلــدول األول فئــة امللحــق لنظــام‬\n      ‫املخــدرات واملؤثــرات العقليــة وبعــد املداهمــة عثــر علــى املبلــغ املرقــم‬\n\n\n‫‪141‬‬\n\f‫علــى الطاولــة حتــت جــوال املدعــى عليــه كمــا عثــر إمامــه علــى ورقــة‬\n‫بهــا تبــغ دخــان يــزن‪ 0.4‬أربعــة إعشــار اجلــرام وقطعــة تــزن ‪2.9‬جرامــن‬\n‫وتســعة إعشــار اجلــرام اثبــت التقريــر الكيمــاوي الشــرعي آنــف الذكــر‬\n‫ايجابيــة عينتهــا ملــادة احلشــيش املخــدر وخلــو التبــغ مــن املــواد املخــدرة و‬\n‫املمنوعــة واتضــح ان الشــخص األخــر يدعــى ‪ ...........‬مت إخــاء ســبيله‬\n‫مــن قبــل شــعبة مكافحــة املخــدرات بالدمــام لعــدم صلتــه بالقضيــة يف‬\n‫حــن أقــر املدعــى عليــه أمــام الفرقــة بقيامــه بالترويــج وأنــه أحضــر‬\n‫احلشــيش املخــدر مــن شــخص يســكن مدينــة ‪ .....‬مبحافظــة القطيــف‬\n‫يلقــب ب‪........‬وبتفتيــش ســيارته مــن نــوع ‪ ......‬حتمــل اللوحــة (‪)........‬‬\n‫اتضــح مــن واقــع احلاســب اآللــي ان ملكيتهــا تعــود للشــركة ‪ ....‬للبيــع‬\n‫بالتقســيط لــم يعثــر بهــا علــى أي شــئ مــن املمنوعــات كمــا نفــى علــم‬\n‫وعالقــة املدعــو‪ .......‬بعمليــة الترويــج وباســتجواب املدعــى عليــه اقــر‬\n‫بتعاطــي احلشــيش املخــدر وبصحــة واقعــة القبــض عليــه وان احــد‬\n‫االشــخاص اتصــل عليــه وطلــب منــه قطعــة حشــيش مخــدرة فأخبــره‬\n‫بأنــه ال يوجــد لديــه حشــيش مخــدر مبــرر ًا وجــود ه يف شــقة املصــدر بأنــه‬\n‫كان معزومـ ًا علــى وجبــة عشــاء يف حــن اقــر إثنــاء ســماع أقوالــه األوليــة‬\n‫منقبــل رجــال الضبــط بشــعبة مكافحــة املخــدرات بالدمــام بقيامــه ببيــع‬\n‫قطعــة حشــيش مخــدر مببلــغ ‪250‬ريــال وحيازتــه للقطعــة املضبوطــة‬\n‫أمامــه بقصــد التعاطــي وتعاطيــه للحشــيش املخــدر نافي ـ ًا علــم وعالقــة‬\n‫مرافقــه بالقضيــة وقــد انتهــى التحقيــق إلــى اتهــام املدعــى عليــه‬\n‫باالتي‪-1:‬ترويــج قطعــة تــزن ‪11.9‬جــرام مــن احلشــيش املخــدر عــن طريق‬\n‫البيــع‪-2 .‬حيــازة قطعــة تــزن‪ 2.9‬مــن احلشــيش املخــدر بقصــد الترويــج‬\n‫والتعاطــي‪-3 .‬تعاطــي مــادة احلشــيش املخــدر وذلــك لألدلــة والقرائــن‬\n\n\n                                                                                        ‫‪142‬‬\n\f      ‫التاليــة‪ -1:‬إقــراره املنــوه عنــه‪-2 .‬مــاورد بأقوالــه األوليــة املنــوه عنهــا‪.‬‬\n      ‫‪-3‬أقــراره املنــوه عنــه‪-4 .‬محضــر القبــض والتفتيــش املنــوه عنــه‪.‬‬\n      ‫‪-5‬التقريــر الكيمــاوي الشــرعي‪ .‬وحيــث أن مــا أقــدم عليــه املدعــى‬\n      ‫عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب شــرع ًا‬\n      ‫ومجــرم نظام ـ ًا وفــق نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وعقوباتــه األصليــة والتكميليــة اطلــب إثبــات مــا اســند إليــه مــن ترويــج‬\n      ‫قطعــة تــزن‪ 11.9‬احــد عشــر جرامــا وتســعة إعشــار اجلــرام مــن مــادة‬\n      ‫احلشــيش املخــدر عــن طريــق البيــع للمــرة الثانيــة وحيــازة قطعــة تــزن‪2.9‬‬\n      ‫جرامــن وتســعة إعشــار اجلــرام مــن نفس املــادة بقصد الترويــج والتعاطي‬\n      ‫وتعاطــي احلشــيش املخــدر وفــق للفقــرة رقــم‪ 2‬مــن املــادة رقــم‪ 3‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه باالتــي ‪-1:‬‬\n      ‫عقوبــة القتــل املنصــوص عليهــا بالفقــرة ‪ 5‬مــن البنــد األول مــن املــادة ‪37‬‬\n      ‫مــن النظــام‪-2 .‬مصــادرة جوالــه مــن نــوع ‪ ....‬يحمــل الرقــم املصنعــي‬\n      ‫والشــريحة الســتخدامه يف ارتــكاب اجلرميــة وفــق الفقــرة ‪1‬مــن املــادة ‪53‬‬\n      ‫مــن النظــام وعــدم صرفهــا لنفــس املتهــم وفق ـ ًا لتعميــم ســمو وزيــر‬\n      ‫الداخليــة رقــم ‪ 9798‬يف ‪1428/2/10‬ه ـ واهلل املوفــق ‪.‬ا‪.‬هــ‪ .‬ويف هــذا‬\n      ‫اليــوم حضــر الطرفــان وباســتجواب املدعــى عليه أجاب قائــا ‪:‬ماذكره‬\n      ‫ا وأنــا كنــت مدعوا‬     ‫املدعــي العــام يف دعــواه غيــر صحيــح جملــة وتفصيـ ً‬\n      ‫لتنــاول طعــام العشــاء عنــد ‪ ........‬الــذي شــقيقه متــزوج أختــي فذهبــت‬\n      ‫إليــه يف منزلــه وبعــد دخولــي الشــقة بدقائــق هجــم علــي ثمانيــة أو عشــرة‬\n      ‫أشــخاص وضربونــي ومــن شــدة الضــرب مــا أدري مــاذا قلــت‪ .‬وبعــرض‬\n      ‫ذلــك علــى املدعــي العــام قــال‪ :‬الصحيــح مــا ذكرتــه ولــدي البينــة وهــم‬\n      ‫الفرقــة القابضــة ومــا يف أوراق املعاملــة وأطلــب رفــع اجللســة إلحضارهــم‬\n\n\n‫‪143‬‬\n\f‫ويف جلســة أخــرى حضــر الطرفــان وقــد جــرى الرجــوع للمعاملــة فوجدنــا‬\n‫علــى اللفــة رقــم (‪ )4-1‬مــن امللــف املرفــق لفــة (‪ )1‬محضــر القبــض‬\n‫والتفتيــش ويتضمــن مــا نصــه‪ :‬نثبــت نحــن املوقعــن أدنــاه بتاريخــه املشــار‬\n‫إليــه أعــاه إلخباريــة أحــد املصــادر الســرية لدينــا مفادهــا معرفتــه‬\n‫لشــخص ســعودي يدعــى باســم ‪........‬يســكن الدمــام حــي ‪........‬يقــوم‬\n‫بترويــج احلشــيش املخــدر وأنــه مســتعد باإلطاحــة بــه باجلــرم املشــهود‬\n‫عليــه مت االنتقــال إلــى حــي ‪........‬جهــة شــارع ‪........‬بالدمــام وكان ذلــك‬\n‫يف حوالــي الســاعة اخلامســة والنصــف قبــل صــاة مغــرب هــذا اليــوم‬\n‫وهنــاك متــت مقابلــة املصــدر والــذي مت متكينــه مــن االتصــال باملــروج‬\n‫وكان ذلــك حتــت مســمع مــن أفــراد الفرقــة علــى جــوال املــروج رقــم‬\n‫‪ .........‬وطلــب منــه بعــد الســام عليــه قطعــة حشــيش بخمســمائة ريــال‬\n‫وأن يحضرهــا لشــقته فوافــق املــروج وقــال ســوف أحضــر إليــك بعــد‬\n‫صــاة املغــرب ومعــي الغــرض عليــه مت عمــل اخلطــة حيــث قــام املصــدر‬\n‫بفتــح منزلــه لنــا يف انتظــار املــروج وجــرى االتصــال علــى املــروج بعــد‬\n‫صــاة املغــرب وقــال ســوف أجيــك بعدهــا جــرى االنتظــار حتــى الســاعة‬\n‫التاســعة مســاء بعــد صــاة العشــاء ولــم يحضــر فـت ــم االتصــال عليــه مــرة‬\n‫أخــرى مــن قبــل املصــدر وقــال لــه يــا أخــي ال تتأخــر علــي ويــن أنــت فقــال‬\n‫املــروج لــم أجــد لــك قطعــة بخمســمائة ريــال وال يوجــد إال قطعــة ب ـ‬\n‫‪250‬ريــا ًال فقــال لــه املصــدر يــا أخــي هاتهــا وتعــال مــا فيــه مشــكلة فقــال‬\n‫املــروج إذ ًا ســوف أحضــر لــك وعطنــي نصــف ســاعة ولكــن املــروج أخــذ‬\n‫مياطــل حتــى الســاعة احلاديــة عشــرة مــن مســاء هــذا اليــوم وكان شــديد‬\n‫احلــذر ويف آخــر اتصــال لــه باملصــدر كان يســأله هــل عنــدك أحــد فــرد‬\n‫عليــه املصــدر مــا عنــدي أحــد وأنــت تعرفنــي ال ميكــن أســمح لــك بــاألذى‬\n\n\n                                                                                         ‫‪144‬‬\n\f      ‫فقــال لــه املــروج إذ ًا افتــح البــاب أنــا عنــد البــاب ودخــل أعضــاء الفرقــة‬\n      ‫إحــدى الغــرف ودخــل املــروج بالصالــة وقابــل املصــدر ثــم خــرج إلحضــار‬\n      ‫احلشــيش وكان حضــوره للشــقة لالطمئنــان وبعــد ربــع ســاعة اتصــل‬\n      ‫باملصــدر وأخبــره بأنــه ســوف يحضــر معــه أحــد أصدقائــه وبعــد دقائــق‬\n      ‫مــن دخولهمــا قــام املصــدر بالدخــول للفرقــة املتواجــدة بأحــد الغــرف‬\n      ‫وقــال أعطونــي املبلــغ فقــام قائــد الفرقــة بتزويــده مبائتــن وخمســن‬\n      ‫ريــا ًال بعدهــا مت اســتالم قطعــة مســتطيلة الشــكل ســوداء اللــون بحجــم‬\n      ‫اإلصبــع يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا مبيــزان‬\n      ‫الشــعبة لدينــا ‪ 11.9‬أحــد عشــر جرام ـ ًا وتســعة مــن العشــرة مــن اجلــرام‬\n      ‫مفيــدا أنهــا الكميــة املروجــة وأن املدعــو باســم ‪........‬هــو مــن أعطــاه‬\n      ‫إياهــا وأن معــه صديــق حضــر معــه وهمــا جالســان بالصالــة وســوف أقــوم‬\n      ‫بإعطائــه املبلــغ وبعــد حلظــات مــن خروجــي مــن الغرفــة قامــوا باملداهمــة‬\n      ‫وعليــه وبعــد خــروج املصــدر مــن الغرفــة وبعــد حلظــات متــت املداهمــة‬\n      ‫حيــث وجــد شــخصان يجلســان أحدهمــا بجانــب املصــدر واآلخــر‬\n      ‫باجلانــب اآلخــر فتــم القبــض عليهمــا حيــث اتضــح أن األول يدعــى ‪..........‬‬\n      ‫ســعودي اجلنســية ال يحمــل إثبــات هويــة وباســتخراج برنــت أحــوال لــه‬\n      ‫وجــد ســجل مدنــي رقــم ‪ .....‬حيــث جــرى تفتيشــه ولــم يعثــر معــه علــى أي‬\n      ‫شــيء مــن املمنوعــات وقــد وجــد املبلــغ احلكومــي أمامــه حتــت جوالــه‬\n      ‫كذلــك عثــر أمامــه علــى ورقــة بهــا فتــات دخــان وكذلــك عثــر أمامــه‬\n      ‫علــى قطعــة صغيــرة ســوداء اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر‬\n      ‫بلــغ وزنهــا مبيــزان الشــعبة لدينــا ‪ 2.9‬جــرام ( جرامــن وتســعة مــن‬\n      ‫العشــرة مــن اجلــرام ) حيــث كان ينــوي فتهــا مــع الســيجارة التــي وجــدت‬\n      ‫مفتوتــة بالورقــة أمــا صديقــه الــذي حضــر معــه فاتضــح أنــه يدعــى ‪.......‬‬\n\n\n‫‪145‬‬\n\f‫ســعودي اجلنســية ال يحمــل إثبــات هويــة وباســتخراج برنــت أحــوال تبــن‬\n‫أنــه يحمــل ســجل مدنــي رقــم ‪ .........‬وبتفتيشــه شــخصي ًا لــم يعثــر معــه‬\n‫علــى أي شــيء مــن املمنوعــات وبســؤال املــروج املدعــو ‪ ..........‬عمــا قــام بــه‬\n‫اعتــرف أمــام الفرقــة بقيامــه بالترويــج وأنهأحضــر احلشــيش مــن شــخص‬\n‫يســكن مدينــة ‪ ........‬مبحافظــة القطيــف يلقــب ب ـ (‪ )...........‬عنده ســيارة‬\n‫‪...........‬رصاصــي وقــد وجــد معــه مفتــاح ســيارته حيــث وجــدت نــوع ‪.....‬‬\n‫اللــون رصاصــي رقــم اللوحــة ‪ .....‬حيــث جــرى تفتيشــها ولــم يعثــر بهــا‬\n‫علــى شــيء مــن املمنوعــات ونطالــب جهــات التحقيق مبصادرتهــا لظلوعه‬\n‫بالترويــج عليهــا وقــد أخذنــا عليــه إقــرار ًا مرفق ـ ًا مبحضرنــا هــذا مبــا‬\n‫قــام بفعلــه وأن املدعــو ‪......‬ليــس لــه عالقــة بالترويــج وال يعــرف عــن‬\n‫احلشــيش الــذي أحضــره أي شــيء عليــه جــرى إخــاء ســبيله علمـ ًا أنــه قد‬\n‫حضــر يف ســيارته نــوع ‪ ..........‬اللــون أبيــض رقــم اللوحــة ‪.........‬وقــد جــرى‬\n‫تفتيشــها ولــم يعثــر بهــا علــى شــيء مــن املمنوعــات عليــه جــرى اصطحابــه‬\n‫ملقــر االدارة وعمــل بحقــه احملضــر الــازم وجــرى التوقيــع عليــه وجــرى‬\n‫تســليمه لضابــط اخلفــر املنــاوب ‪.‬ا‪.‬هــ‪ .‬كمــا جــرى االطــاع علــى إقــرار‬\n‫املدعــى عليــه املــدون علــى اللفــة (‪ )3‬ويتضمــن ‪ :‬اقــر أنــا املدعــو ‪ ......‬وأنــا‬\n‫بكامــل قــواي العقليــة املعتبــرة شــرعا وبــدون إكــراه أو إجبــار مــن أحــد‬\n‫بأنــي قمــت ببيــع قطعــة حشــيش بحجــم االصبــع علــى مصــدر املكافحــة‬\n‫مســاء هــذا اليــوم مببلــغ مائتــن وخمســن ريــا ًال وقــد احضرتهــا لــه يف‬\n‫شــقته وقمــت بتســليمها لــه يف شــقته بعــد اســتالمي املبلــغ منــه ووضعتــه‬\n‫علــى الطاولــة التــي أمامــي باملجلــس حتــت جوالــي علمــا بأنــي أحضــر‬\n‫قطعــة احلشــيش هــذه مــن شــخص يلقــب ‪......‬مــن ســكان ‪.....‬يركــب‬\n‫ســيارة ‪ ........‬فضيــة كذلــك القطعــة الصغيــرة التــي قمــت مبحاولــة فتهــا‬\n\n\n                                                                                           ‫‪146‬‬\n\f      ‫وأنــا جالــس مبجلــس مصــدر املكافحــة قبــل القبــض علــي مــن رجــال‬\n      ‫املكافحــة ‪.‬ا‪.‬هــ‪ .‬وبعــرض مــا ورد يف محضر القبــض والتفتيش واإلقرار‬\n      ‫علــى املدعــى عليــه قــال ‪ :‬مــا جــاء يف احملضــر واإلقــرار غيــر صحيــح فلــم‬\n      ‫أقــم ببيــع قطعــة احلشــيش املذكــورة وأنــا ال أروج احلشــيش املخــدر ‪.‬‬\n      ‫كمــا وجدنــا علــى الصفحــة(‪ )5‬مــن ملــف التحقيــق املرفــق باملعاملــة لفــه‬\n      ‫(‪ )1‬إقــرار ًا للمدعــى عليــه يف جوابــه علــى أســئلة احملقــق ومنهــا ‪ :‬س‪/‬‬\n      ‫اشــرح لــي كيــف مت القبــض عليــك ؟ ج‪ /‬اتصــل علـ ّـي أحــد األشــخاص‬\n      ‫الذيــن أعرفهــم وطلــب منــي قطعــة حشــيش بقيمــة خمســمائة ريــال وقلــت‬\n      ‫لــه إن املوجــود مبئتــن وخمســن فقــط عندهــا وافــق وأحضــرت لــه‬\n      ‫القطعــة وســلمتها لــه واســتلمت املبلــغ بعدهــا جــرى القبــض علـ ّـي‬\n      ‫وإحضــاري إلــى هنــا ‪ .‬س‪ /‬إذا أنــت تقــر بترويــج احلشــيش ؟ج‪ /‬نعــم ‪ .‬س‪/‬‬\n      ‫ومــاذا عــن القطعــة املضبوطــة معــك بعــد الترويــج ؟ ج‪ /‬نعــم هــذه قطعــة‬\n      ‫صغيــرة كانــت معــي لقصــد االســتخدام ‪ .‬ا‪.‬هــ‪ .‬وباســتجواب املدعــى‬\n      ‫عليــه عمــا جــاء يف اقــراره حتقيقــا قــال ‪ :‬مــا جــاء يف التحقيــق غيــر‬\n      ‫صحيــح فلــم أقــل أنــا هــذا الــكالم ‪.‬وقــد جــرى االطــاع علــى التقريــر‬\n      ‫الكيمــاوي املشــار إليــه يف دعــوى املدعــي العــام علــى اللفــة (‪)25‬‬\n      ‫والصــادر مــن مــن املركــز االقليمــي ملراقبــة الســموم برقــم ‪........‬يف‬\n      ‫‪1430/7/7‬ه ــواملتضمن ‪ :‬املرســل عبــارة عــن حــرز ظــرف حكومــي‬\n      ‫وجــد بداخلــه ‪ )1 :‬العينــة رقــم ‪........‬وهــي عبــارة عــن كيــس بالســتيك‬\n      ‫شــفاف عــدمي اللــون بــه قطعــة بنيــة اللــون تــزن مبيــزان القســم صــايف ‪0.3‬‬\n                  ‫ثالثة بالعشرة من اجلرام ثبت ايجابيتها ملادة احلشيش املخدرة ‪.‬‬\n      ‫‪ )2‬العينــة رقــم ‪/728‬أ وهــي عبــارة عــن كيــس بالســتيك شــفاف عــدمي‬\n      ‫اللــون بــه تبــغ يــزن مبيــزان القســم قائــم بالكيــس ‪ 1.2‬ثبــت خلــوه مــن‬\n\n\n‫‪147‬‬\n\f‫املــواد املخــدرة ‪ )3 .‬العينــة رقــم ‪........‬وهــي عبــارة عــن كيــس بالســتيك‬\n‫شــفاف عــدمي اللــون بــه قطعــة بنيــة تــزن ‪ 0.3‬مــن العشــرة مــن اجلــرام‬\n‫ثبــت إيجابيتهــا ملــادة احلشــيش املخــدرة ‪.‬ا‪.‬هــ‪ .‬كمــا جــرى االطــاع علــى‬\n‫الســابقة املســجلة علــى املدعــى عليــه ‪........‬املثبتــة بالصــك رقــم‪................‬‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة املســتعجلة بالدمــام ‪................‬‬\n‫واملرفــق صــورة منــه علــى اللفــة رقــم‪ ................‬املصــادق عليهــا مــن‬\n‫اإلدارة العامــة ملكافحــة املخــدرات ونــص املقصــود منــه ‪ :‬فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واالجابــة ومبــا أن املدعــى عليهمــا اقــرا بدعــوى‬\n‫املدعــي العــام ‪ ..‬فقــد قــررت أوال ثبــوت ادانــة املدعــى عليــه االول ‪......‬‬\n‫بترويــج مــا وزنــه ‪ 44,2‬مــن احلشــيش املخــدر عــن طريــق البيــع ‪ ..‬ا‪.‬ه ـ ‪.‬‬\n‫وكنــا قــد اطلعنــا علــى الصــك املرفــق باملعاملــة والصــادر مــن فضيلــة‬\n‫القضــاة ســلفنا ووجــد فيــه أنــه حضــر لديهــم اثنــان مــن الفرقــة القابضــة‬\n‫وهما‪..........‬و‪...........‬بصحــة مــا ورد يف محضــر القبــض إال أنهمــا لــم‬\n‫يشــاهدا اســتالم وتســليم بــن املصــدر واملدعــى عليــه وشــهادتهم مجملــة‬\n‫يف ذلــك ‪ .‬كمــا جــرى ســؤال املدعــى عليــه هــل كان متعاطيـ ًا للحشــيش‬\n‫املخــدر وقــت القبــض عليــه وهــل هــو يتعاطــى احلشــيش ‪ .‬فأجــاب بقولــه‬\n‫‪ :‬ال أتعاطــى احلشــيش املخــدر ولــم أكــن متعاطيـ ًا لــه وقــت القبــض علـ ّـي‬\n‫‪ .‬فبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه ملــا‬\n‫جــاء يف دعــوى املدعــي العــام وبنــاء علــى محضــر القبــض والتفتيــش‬\n‫املذكــور بعاليــه وملــا جــاء يف إقــرار املدعــى عليــه أثنــاء التحقيــق معــه‬\n‫املذكــور بعاليــه وبنــاء علــى التقريــر الكيميائــي املشــار إليــه بعاليــه وملــا‬\n‫جــاء يف شــهادة الشــهود لــدى ســلفنا التــي يف الصــك املشــار إليــه بعاليــه‬\n‫ولســوابق املدعــى عليــه املذكــورة ولعظــم ضــرر املخــدرات وإفســادها‬\n\n\n                                                                                            ‫‪148‬‬\n\f      ‫للعقــول واألديــان وانتشــارها بشــدة يف هــذا الزمــان ونظــر ًا ألن الشــهود‬\n      ‫لــم يشــهدوا باالســتالم والتســليم وجــاءت شــهادتهم مجملــة لــدى القضــاة‬\n      ‫ســلفنا ونظــرا لقلــة الكميــة املضبوطــة جــدا فبنــاء علــى كل ماتقــدم‬\n      ‫فقررنــا باإلجمــاع مايلــي أوال ‪ :‬لــم يثبــت لدينــا إدانــة املدعــى عليــه ترويــج‬\n      ‫مــا وزنــه أحــد عشــر جرامــا وتســعة مــن العشــرة مــن اجلــرام مــن احلشــيش‬\n      ‫املخــدر وإلدانتــه بحيــازة جرامــن وتســعة مــن العشــرة مــن اجلــرام مــن‬\n      ‫احلشــيش املخــدر ثانيــا ‪ :‬صرفنــا النظــر عــن طلــب املدعــي العــام تطبيــق‬\n      ‫الفقرة (‪ )5‬من البند أوال من املادة الســابعة والثالثني من النظام املشــار‬\n      ‫إليــه ثالثــا ‪ :‬قررنــا تعزيــر املدعــى عليــه بســجنه أربــع ســنوات ابتــداء ًا مــن‬\n      ‫تاريــخ إيقافــه وجلــده خمســمائة جلــدة مفرقــة علــى عشــر دفعــات كل‬\n      ‫دفعــة خمســن جلــدة بــن كل دفعــة وأخــرى خمســة عشــر يومـ ًا علــى أن‬\n      ‫تكــون األولــى واألخيــرة معلنــة أمــام ‪ ................‬بحــي ‪........‬لقــاء الشــبهة‬\n      ‫القويــة بحقــه بترويــج ‪11.9‬مــن اجلــرام وحيــازة ‪ 2.9‬مــن اجلــرام وبذلــك‬\n      ‫حكمنــا وبعرضــه علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم‬\n      ‫وقــرر املدعــي العــام اعتراضــه علــى احلكــم وطلــب رفــع املعاملــة إلــى‬\n      ‫محكمــة االســتئناف فجــرى إفهامــه بالنظــام يف ذلــك وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                           ‫‪ 1434/04/08‬هــ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالريــاض مرفقــا بهــا القــرار رقــم ‪................‬وتاريــخ ‪................‬هـ الصادر‬\n      ‫مــن فضيلــة قضــاة الدائــرة الثانيــة لتمييــز القضايــا اخلماســية املصادقــة‬\n                 ‫باألكثريــة علــى احلكــم وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n‫‪149‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":139,"source_page_end":149,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b9d8d158fd94a6701b0476b57d12e2ea0cba68e83cf8658493cfe38621586660","normalized_text_hash":"0b4047ec5276b393f12cbddab89023cfa223daa8e89351a3d400c25637695263","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p139-34209535"},{"id":"696a98ec-812a-50e2-90ef-afc28d880a4b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش املخدر -ترويج احلشيش املخدر - رجوع عن إقرار -وجود سوابق من جنس اجلناية -ثبوت إدانته -تعزير بالسجن واجللد ومصادرة اجلوال وتغرمية مالي ا -صرف النظر عن مصادرة املبلغ املضبوط واملنع من السفر.","document_number":"3394934","case_number":"7823","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/2/21","year":"1434","subject":"مخدرات -تعاطي احلشيش املخدر -ترويج احلشيش املخدر - رجوع عن إقرار -وجود سوابق من جنس اجلناية -ثبوت إدانته -تعزير بالسجن واجللد ومصادرة اجلوال وتغرمية مالي ا -صرف النظر عن مصادرة املبلغ املضبوط واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3394934 :‬تاريخه‪1433/2/21 :‬هـ‬\n                       ‫رقم الدعوى‪7823:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 33443481‬تاريخه‪1433/11/1 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬ترويــج احلشــيش املخــدر ‪-‬‬\n‫رجــوع عــن إقــرار ‪ -‬وجــود ســوابق مــن جنــس اجلنايــة‪ -‬ثبــوت إدانتــه‬\n‫‪ -‬تعزيــر بالســجن واجللــد ومصــادرة اجلــوال وتغرميــة مالي ـ ًا ‪ -‬صــرف‬\n               ‫النظــر عــن مصــادرة املبلــغ املضبــوط واملنــع مــن الســفر‪.‬‬\n\n\n\n\n‫املــادة (‪ )3‬واملــادة (‪ )37‬و املــادة (‪ )57‬واملــادة (‪ )60‬مــن نظــام مكافحــة‬\n                                         ‫املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات ( احلشــيش‬\n‫املخــدر )‪ ،‬حيــث مت القبــض علــى املدعــى عليــه وهــو مبنزلــه وبحوزتــه‬\n‫قطعــة احلشــيش وقــد أثبــت التقريــر إيجابيــة العينــة ملــادة احلشــيش ‪،‬‬\n‫أقــر املدعــى عليــه بصحــة واقعــة القبــض إثــر حيازتــه احلشــيش املخــدر‬\n‫بقصــد الترويــج والتعاطــي ‪ ،‬أثبــت التقرير الكيميائي الشــرعي احتواء‬\n‫املــادة املضبوطــة علــى احلشــيش‪ ،‬لــذا طلــب املدعــي العــام باحلكــم‬\n‫علــى املدعــى عليــه بعقوبــة القتــل التعزيريــة ومصــادرة هاتفــه اجلــوال‬\n‫الســتخدامه يف عمليــة الترويــج ومصــادرة املبلــغ املالــي املضبــوط‪ ،‬صــدر‬\n‫احلكــم بجلــده حــد املســكر ثمانــن جلــدة دفعــة واحــدة علنـ ًا ‪ ،‬احتياطا‬\n\n                                                                                  ‫‪150‬‬\n\f      ‫للدمــاء وللقرائــن والتهــم ‪ ،‬قــررت احملكمــة النــزول عــن عقوبــة القتــل‬\n      ‫التعزيريــة إلنــكار املدعــى عليــه دعــوى الترويــج أثنــاء احملاكمــة ‪،‬‬\n      ‫وقــررت ســجن املدعــى عليــه تعزيــرا عشــر ســنوات وجلــده ألــف جلــدة‬\n      ‫مفرقــة علــى عشــرين دفعــة متســاوية بــن كل دفعــة وأخــرى مــا ال يقــل‬\n      ‫عــن أســبوع ‪ ،‬ومصــادرة اجلــوال مــع تغرميــه مائــة ألــف ري ــال ‪ ،‬وصــرف‬\n      ‫النظــر عــن مصــادرة املبلــغ املالــي املضبــوط إلنــكاره أنــه متحصــل‬\n      ‫مــن بيــع املخــدرات ‪ ،‬ومنعــه مــن الســفر خــارج البــاد بعــد خروجــه مــن‬\n      ‫الســجن ملــدة عشــر ســنوات‪ ،‬ومت تصديــق احلكــم مــن قبــل محكمــة‬\n                                                                      ‫االســتئناف‪.‬‬\n\n\n\n\n      ‫ـاء علــى املعاملــة‬\n                         ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة ‪.......‬وبنـ ً‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالدمــام برقــم ‪.......‬‬\n      ‫وتاريــخ ‪ .......‬ه ـ املقيــدة باحملكمــة برقــم ‪ .......‬وتاريــخ ‪.......‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافق‪.......‬ه ـ حضــر املدعــي العــام ‪ .......‬ســعودي اجلنســية‬\n      ‫ا ‪ :‬حيــث إنــه‬  ‫مبوجــب الســجل املدنــي رقــم (‪ ).......‬وادعــى األول قائ ـ ً‬\n      ‫باإلطــاع علــى محاضــر البــاغ و االنتقــال و القبــض و التفتيــش املعــدة‬\n      ‫مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة املخــدرات تبــن أنــه ورد‬\n      ‫بــاغ مــن أحــد املصــادر عــن وجــود شــخص يدعــى‪،....... /‬يســكن يف‬\n      ‫مخطــط (‪ ) .......‬ويقــوم بترويــج احلشــيش املخــدر و عليــه مت االنتقــال إلــى‬\n      ‫منزل املذكور و مراقبته لعدة أيام و يف متام الســاعة التاســعة من مســاء‬\n      ‫يــوم االثنــن املوافــق ‪.......‬ه ـ شــوهد شــخص يحتــك باملدعــى عليــه أمــام‬\n      ‫منزلــه و بعدهــا انصــرف و مبراقبتــه و القبــض عليــه عثــر بحوزتــه علــى‬\n\n‫‪151‬‬\n\f‫حشــيش مخــدر و بســؤاله عــن كيفيــة حصولــه علــى احلشــيش املخــدر‬\n‫أجــاب أنهــا مــن املدعــو ‪ (....... /‬املدعــى عليــه ) و يف متــام الســاعة التاســعة‬\n‫مــن مســاء يــوم الســبت املوافــق ‪.......‬ه ـ شــوهد شــخص يوقــف ســيارته‬\n‫أمــام منــزل املدعــى عليــه و دخــل عليــه تــارك ًا خلفــه محــرك الســيارة يف‬\n‫وضــع التشــغيل و بعــد دقيقــة خــرج نفــس الشــخص مــن املنــزل و بتعقبــه‬\n‫و القبــض عليــه عثــر بحوزتــه علــى حشــيش مخــدر و بســؤاله عــن مصــدر‬\n‫حصولــه عليــه أجــاب أنــه مــن املدعــى عليــه ‪ ،‬و خشــية مــن اســتمراره يف‬\n‫الترويــج مت أخــذ األذن مبداهمتــه و يف متــام الســاعة الثانيــة عشــرة مــن‬\n‫نفــس اليــوم متــت املداهمــة و شــوهد املدعــى عليــه جالس ـ ًا يف املجلــس و‬\n‫مت القبــض عليــه و بتفتيشــه لــم يعثــر معــه علــى أي شــيء مــن املمنوعــات‬\n‫و بتفتيــش املوقــع الــذي كان يجلــس فيــه وجــد شــنطة ســوداء عثــر‬\n‫بداخلهــا علــى قطعــة بلــغ وزنهــا (‪ )122.3‬مائــة و اثنــان و عشــرون جرامـ ًا‬\n‫و ثالثــة أعشــار اجلــرام كمــا عثــر علــى قطعتــن بلــغ وزنهــا ( ‪ )11.7‬أحــد‬\n‫عشــر جرامـ ًا و ســبعة أعشــار اجلــرام معــدة للترويــج ‪ ،‬و قــد أثبــت القريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ )........‬و تاريــخ ‪1431/5/28‬ه ـ ايجابيــة‬\n‫عينــة املــادة املضبوطــة للحشــيش املخــدر املــدرج باجلــدول (‪ )1‬فئــة (أ)‬\n‫املرفــق بنظــام مكافحــة املخــدرات ‪ ،‬كمــا عثــر علــى مبلــغ مالــي قــدره‬\n‫( ‪ ) 8300‬ثمانيــة آالف و ثالثمائــة ريــال كمــا عثــر علــى أدوات تقطيــع‬\n‫و تغليــف احلشــيش املخــدر و بتفتيــش املنــزل عثــر علــى رشــاش ‪.... ( .....‬‬\n‫) بداخــل غرفــة النــوم حتــت الســرير و علــى ذخائــر حيــة عــدد ( ‪) 62‬‬\n‫و مخزنــن فارغــن مــن الرصــاص ( مت فــرز أوراق خاصــة بالســاح و‬\n‫الذخيــرة ) و بســؤاله عــن األشــخاص الذيــن روج عليهــم و مت القبــض‬\n‫عليهــم مــن قبــل الفرقــة أقــر بالترويــج لنفــس األشــخاص ‪ .‬كمــا تبــن أن‬\n\n\n                                                                                          ‫‪152‬‬\n\f      ‫املدعــى عليــه ســبق و أن أديــن بالترويــج مبوجــب القــرار الشــرعي رقــم‬\n      ‫( ‪ ) .......‬و تاريــخ ‪ ........‬وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة‬\n      ‫القبــض عليــه مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة املخــدرات‬\n      ‫إثــر حيازتــه احلشــيش املخــدر بقصــد الترويــج و التعاطــي و أفــاد أنــه‬\n      ‫بــاع حشــيش مخــدر لشــخصني مببلــغ مائتــن ريــال لــكل واحــد منهمــا‬\n      ‫مضيف ـ ًا تعاطيــه للحشــيش املخــدر و أن اجلــوال الــذي كان يســتخدمه‬\n                                 ‫مــن نــوع ‪ ....‬رقمــه ( ‪ ).......‬و نفــى مــا ســوى ذلــك‪.‬‬\n                              ‫و قد انتهى التحقيق إلى اتهام املدعى عليه باآلتي ‪:‬‬\n                                     ‫‪ -1‬بيع مادة احلشيش املخدر بقصد االجتار ‪.‬‬\n      ‫‪ -2‬حيــازة مــا وزنــه (‪ )134‬مائــة و أربعــة و ثالثــون جرام ـ ًا مــن مــادة‬\n                                 ‫احلشــيش املخــدر بقصــد الترويــج والتعاطــي ‪.‬‬\n                                                   ‫‪ -3‬تعاطيه مادة احلشيش املخدر ‪.‬‬\n                                                       ‫وذلك لألدلة والقرائن األتية ‪:‬‬\n      ‫‪ -1‬اعترافــه مبــا نســب إليــه املنــوه عنــه املــدون علــى اللفــات رقــم ( ‪-15‬‬\n                                                                                    ‫‪. ) 18‬‬\n      ‫‪ -2‬محاضــر البــاغ و الترقيــم و االنتقــال و القبــض و التفتيــش املنــوه‬\n      ‫عنهــا واملدونــة علــى الصفحــات رقــم ( ‪ ) 4 - 2‬مــن امللــف املرفــق علــى‬\n                                                                         ‫اللفــة رقــم (‪. )1‬‬\n                         ‫‪ -3‬حيازة أدوات التقطيع و التغليف قرينة على الترويج ‪.‬‬\n      ‫‪ -4‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم‬\n                                                                                   ‫(‪. )28‬‬\n      ‫و حيــث إن ماأقــدم عليــه املدعــى عليــه و هــو بكامــل أهليــه املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم و معاقــب عليــه شــرع ًا و مجــرم نظام ـ ًا مبوجــب‬\n\n\n‫‪153‬‬\n\f‫نظــام مكافحــة املخــدرات و املؤثــرات العقليــة يف عقوبــة األصليــة و‬\n                                                 ‫التكميليــة أطلــب مــا يلــي‪-:‬‬\n‫أو ًال ‪ :‬اثبــات مــا أســند إليــه اســتنادا للفقــرة ( ‪ ) 2‬مــن املــادة ( ‪ ) 3‬مــن‬\n‫نظــام مكافحــة املخــدرات و املؤثــرات العقليــة و احلكــم عليــه باآلتــي‪-:‬‬\n‫‪ -1‬عقوبــة القتــل التعزيريــة املنصــوص عليهــا بالفقــرة ( ‪ ) 5‬مــن البنــد (‬\n‫أو ًال ) مــن املــادة (‪ )37‬مــع مراعــاة ماتقضــي بــه املــادة (‪ )62‬مــن النظــام ‪.‬‬\n‫‪ -2‬مصــادرة هاتفــه اجلــوال الــذي مــن نــوع ‪ ....‬ذي الرقــم املصنعــي (‪).....‬‬\n‫الســتخدامه يف عمليــة الترويــج وفــق الفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن‬\n                                                                          ‫النظــام ‪.‬‬\n‫‪3‬ـ مصــادرة املبلــغ املالــي املضبــوط و الــذي قــدره ( ‪ ) 8300‬ثمانيــة آالف‬\n‫و ثالثمائــة ريــال و فق ـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )53‬لكونهــا متحصلــة‬\n                                                         ‫مــن ترويــج املخــدرات ‪.‬‬\n    ‫ثانيا‪ :‬احلكم عليه باملقتضى الشرعي لقاء تعاطيه احلشيش املخدر ‪.‬‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫العــام مــن مداهمــة منزلــي و وجــود شــنطة ســوداء عثــر بداخلهــا علــى‬\n‫قطعــة احلشــيش املذكــور وزنهــا صحيــح وكذلــك وجــود قطعتــن‬\n‫صغيرتــن صحيــح ولكنهمــا ليســتا معدتــا للترويــج وإمنــا الســتخدامي‬\n‫الشــخصي واملبلــغ املذكــور عائــد لزوجتــي رصد لدفــع إيجار البيت وانا‬\n‫أتعاطــى احلشــيش املخــدر ومدمــن لــه واجلــوال املذكــور لــي واســتخدمه‬\n‫إذا رغبــت يف شــراء احلشــيش بغــرض التعاطــي وليــس الترويــج وأمــا مــا‬\n‫ذكــره املدعــي العــام مــن ترويجــي لشــخصني غيــر صحيــح فأنــا ال أروج‬\n‫احلشــيش وســألت الطرفني عن الســوابق فقاال على املدعى عليه ســابقة‬\n‫ترويــج حكــم عليــه بهــا شــرع ًا وبعــرض اجلــواب علــى املدعــي العــام قــال‬\n\n\n                                                                                        ‫‪154‬‬\n\f      ‫الصحيــح مــا ذكرتــه وبينتــي عليــه اعترافــه حتقيقـ ًا ومــا ذكــر مــن أدلــة‬\n      ‫وقرائــن يف الدعــوى ‪ .‬ويف جلســة ‪1433/01/05‬ه ـ لدينــا نحــن القضــاة‬\n      ‫‪ .......‬حضــر الطرفــان وســئل الطرفــان عــن الســوابق فقــال املدعــى عليــه‬\n      ‫ســابقة ترويــج مخــدرات ثبــت فيهــا إدانتــي شــرع ًا وصادقــه املدعــي‬\n      ‫العــام علــى ذلــك وعلــى اللفــة رقــم (‪ )17‬محضــر اســتجواب املدعــى‬\n      ‫عليــه وفيــه اعترافــه ببيــع احلشــيش املخــدر علــى أشــخاص وقــد تضمــن‬\n      ‫مــا نصــه ‪ ( :‬س ‪ /‬يفيــد محضــر القبــض بأنــك قمــت ببيــع احلشــيش‬\n      ‫املخــدر علــى أشــخاص قبــل القبــض عليــك فمــن هــؤالء األشــخاص؟ ج‪/‬‬\n      ‫شــخص يدعــى ‪.......‬بعتــه قطعــة مــن احلشــيش املخــدر مببلــغ مائتــن ريــال‬\n      ‫وشــخص يدعــى ‪.......‬بعتــه قطــع مــن احلشــيش املخــدر أيض ـ ًا مبائتــن‬\n      ‫ريــال ) وبعرضــه علــى املدعــى عليــه قــال االعتــراف غيــر صحيــح ولــم‬\n      ‫يصــدر منــي كمــا وجــد علــى اللفــة رقــم (‪ )23‬الئحــة بســوابق املدعــى‬\n      ‫عليــه وهــي واحــدة يف ترويــج املخــدرات وبعــرض محضــر االســتجواب‬\n      ‫علــى اللفــات رقــم (‪ 16‬و ‪ 17‬و ‪ )18‬قــال كل مــا فيــه صحيــح باســتثناء‬\n      ‫مــا يتعلــق باعتــرايف اننــي بعــت احلشــيش ‪ ..............‬ابــن خالــي واصغــر‬\n      ‫منــي ســن ًا وعلــى اللفــة رقــم (‪ )28‬تقريــر كيمــاوي شــرعي رقــم (‪)........‬‬\n      ‫يتضمــن ايجابيــة العينتــن املرســلتني ملــادة احلشــيش املخــدر والعينتــان‬\n      ‫تخــص املدعــى عليــه حســب مــا جــاء يف رأس كتــاب املركــز األقليمــي‬\n      ‫ملراقبــة الســموم علــى اللفــة رقــم (‪ )29‬كمــا وجــد علــى اللفــات مــن (‪32‬‬\n      ‫‪ )39 -‬صــورة قــرار شــرعي صــادر مــن احملكمــة اجلزئيــة باخلبــر برقــم‬\n      ‫(‪ )3/53‬يف ‪1427/3/4‬ه ـ يتضمــن ثبــوت إدانــة املدعــى عليــه بترويــج‬\n      ‫احلشــيش املخــدر ويف جلســة ‪ 1433/02/16‬ه ـ لدينــا نحــن القضــاة ‪.......‬‬\n      ‫حضــر الطرفــان وســئل املدعــى عليــه عــن بصمتــه التــي ذيــل بهــا محضــر‬\n\n\n‫‪155‬‬\n\f‫االســتجواب املرفــق باملعاملــة علــى اللفــات رقــم (‪ )18،17،16‬فقــال‬\n‫هــي بصمتــي وســئل املدعــي العــام عــن بينتــه علــى أن املبلــغ املضبــوط‬\n‫املذكــور يف الدعــوى متحصــل مــن ترويــج املخــدرات فقــال بينتــي وجوده‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬   ‫يف الشــقة فقــط ‪ .‬فبنـ ً‬\n‫اعتــرف املدعــى عليــه بتعاطــي احلشــيش املخــدر واعتــرف بحيازتــه‬\n‫للحشــيش املخــدر املذكــور وزنــه وصفتــه يف الدعــوى واعتــرف أنــه‬\n‫يســتخدم اجلــوال املذكــور إذا رغــب يف شــراء احلشــيش ومبــا انــه جــاء‬\n‫يف اعترافــه أثنــاء اســتجوابه حتقيقاًأنــه بــاع احلشــيش علــى شــخصني‬\n‫وأنكــر اعترافــه أثنــاء محاكمتــه عندنــا وقــد أقــر مبــا يف اســتجوابه‬\n‫ســوى االعتــراف بالبيــع وأقــر ببصمتــه علــى االســتجواب وبعــد االطــاع‬\n‫علــى املــادة الثالثــة واملــادة الســابعة والثالثــن واملــادة الســابعة اخلمســن‬\n‫واملــادة الســتني مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة قررنــا‬\n                                                                         ‫مــا يلــي‪-:‬‬\n‫أو ًال ‪ :‬جلــد املدعــى عليــه حــد املســكر ثمانــن جلــدة دفعــة واحــدة علنـ ًا‬\n                                                                 ‫يف مــكان عــام‪.‬‬\n      ‫ثانياً‪ :‬ثبت لدينا إدانة املدعى عليه بترويج احلشيش املخدر وحيازته‪.‬‬\n‫ثالث ـ ًا ‪ :‬قررنــا النــزول عــن عقوبــة القتــل إلنــكاره دعــوى الترويــج اثنــاء‬\n‫محاكمتــه وقررنــا تعزيــره بالســجن ملــدة عشــر ســنوات اعتبــار ًا مــن‬\n‫تاريــخ توقيفــه يف ‪.......‬ه ـ وجلــده ألــف جلــدة مفقــرة علــى عشــرين دفعــة‬\n‫متســاوية بــن كل دفعــة وأخــرى مــا اليقــل عــن اســبوع وتنفــذ إحــدى‬\n‫الدفعــات قريب ـ ًا مــن أحــد جوامــع حــي‪ ........‬بالدمــام بعــد صــاة اجلمعــة‬\n                                       ‫وأخــرى تنفــذ يف حــي ‪........‬بالدمــام ‪.‬‬\n                        ‫رابع ًا ‪ :‬مصادرة هاتفه اجلوال املوصوف يف الدعوى‪.‬‬\n\n\n                                                                                        ‫‪156‬‬\n\f                                                          ‫خامس ًا ‪ :‬تغرميه مائة ألف ريال ‪.‬‬\n      ‫سادس ـ ًا ‪ :‬صــرف النظــر عــن مصــادرة املبلــغ املضبــوط املوصــوف يف‬\n      ‫الدعــوى إلنــكار املدعــى عليــه علــى أنــه متحصــل مــن بيــع احلشــيش‬\n                                             ‫املخــدر وعــدم البينــة مــن املدعــي العــام‪.‬‬\n      ‫ســابع ًا ‪ :‬منعــه مــن الســفر خــارج اململكــة بعــد خروجــه مــن الســجن‬\n      ‫ملــدة عشــر ســنوات وبذلــك أجمعــه حكمنــا وبعــرض احلكــم علــى‬\n      ‫ا‪:‬‬ ‫الطرفــن طلبــا متييــزه فأجيبــا لطلبهمــا وأفــاد املدعــى عليــه قائ ـ ً‬\n      ‫إعتراضــي فقــط علــى مــدة الســجن ألنهــا طويلــة وأنــا أب لطفلــة عمرهــا‬\n      ‫ســبع ســنوات وســجني هــذه الفتــرة يؤثــر عليهــا ســلب ًا وال أرغــب يف تقــدمي‬\n      ‫الئحــة إعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                               ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ .......‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد بشــأن دعــوى ‪ /‬املدعــي العــام ضــد ‪....... /‬فقــد‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا‬\n      ‫قرارهــا رقــم ‪ .......‬وتاريــخ ه ـ املتضمــن مانصــه (بدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة لوحــظ مــا يلــي‪ :‬أو ًال ‪ -‬أثبــت أصحــاب‬\n      ‫الفضيلــة إدانــة املدعــى عليــه بترويــج احلشــيش املخــدر ولــم يوضحــوا‬\n      ‫أنــه للمرةالثانيــة ‪ .‬ثاني ـ ًا ‪ -‬اثبــت أصحــاب الفضيلــة إدانــة املدعــى عليــه‬\n      ‫بحيازتــه احلشــيش املخدرولــم يبينــوا القصــد مــن ذلــك ‪ .‬ثالث ـ ًا ‪ -‬اثبــت‬\n      ‫أصحــاب الفضيلــة إدانــة املدعــى عليــه بترويــج احلشــيش املخــدر رغــم‬\n      ‫انــكاره لديهــم ‪ .‬رابع ـ ًا ‪ -‬قــرر أصحــاب الفضيلــة النــزول عــن عقوبــة‬\n      ‫القتــل النــكاره دعــوى الترويــج بينمــا اثبتــوا يف ثاني ـ ًا ادانتــه بالترويــج‬\n      ‫ويف ذلــك تناقــض ‪ ).‬واجلــواب مــا يلــي ‪ :‬أو ًال ‪ /‬ســبق أن ذكرنــا أن‬\n      ‫املدعــى عليــه عليــه ســابقة ترويــج املخــدرات وتصــادق الطرفــان علــى‬\n\n\n‫‪157‬‬\n\f‫ذلــك وأشــرنا إلــى مــا يــدل علــى الســابقة مــن ملعاملــة وهــي اللفــة رقــم‬\n‫(‪ )23‬وأشــرنا إلــى القــرار الشــرعي املرفــق صورتــه علــى اللفــات مــن ‪32‬‬\n‫إلــى ‪ 39‬واملقصــود أنــه ثبــت لدينــا إدانتــه بالترويــج للمــرة الثانيــة ثانيـ ًا ‪/‬‬\n‫أثبتنــا إدانتــه بترويــج احلشــيش املخــدر وحيازتــه فكيــف يقــال لــم نثبــت‬\n‫ـاء‬\n‫القصــد مــن احليــازة ثالث ـ ًا ‪ /‬اثبتنــا إدانــة املدعــى عليــه بالترويــج بنـ ً‬\n‫علــى اعترافــه حتقيق ـ ًا أنــه بــاع احلشــيش علــى شــخصني وأقــر ببصمتــه‬\n‫علــى االســتجواب رابع ـ ًا ‪ /‬ليــس عندنــا تناقــض فالترويــج ثابــت عندنــا‬\n‫إدانتــه بــه والنــزول عــن عقوبــة القتــل ســببه إنــكاره دعــوى الترويــج‬\n‫ـاء علــى‬\n        ‫أثنــاء محاكمتــه كمــا جــاء يف نــص حكمنــا وثبــوت اإلدانــة بنـ ً‬\n‫االعتــراف الســابق الــذي بصــم عليــه واعتــرف ببصمتــه عليــه ولكــن‬\n‫االحتيــاط للدمــاء جعــل إنــكاره أثنــاء احملاكمــة مبرراًلنــا للنــزول عــن‬\n‫عقوبــة القتــل هــذا مــا ظهــر لنــا ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                        ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ .......‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام‬\n‫برقــم ‪.......‬وتاريــخ ‪.......‬واملقيــدة لــدى احملكمــة برقــم ‪.......‬وتاريــخ‬\n‫‪1434/2/2‬ه ـ املرفــق بهــا القــرار الشــرعي ذو الرقــم ‪.......‬والتاريــخ ‪.......‬‬\n‫الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪ ......./‬يف‬\n‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا‬\n‫هــو مــدون ومفصــل فيــه ‪ .‬وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة علــى‬\n‫قرارنــا رقــم ‪ .......‬وتاريــخ ‪.......‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد‬\n\n\n                                                                                           ‫‪158‬‬\n\f      ‫اإليضــاح واإلجــراء األخيريــن‪.‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                             ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪159‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":150,"source_page_end":159,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e3e57cc45ecb4e7e06e7c8dc2d96aade6381d0eabd9b1cb9e7a1c07ff0da9966","normalized_text_hash":"70fa4389a24131cb67abec41100e5f9b5077d61fb85244b2365e64408560bea8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p150-3394934"},{"id":"d186f337-ff2b-5a1a-b72a-5f4d7b8ec5ec","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -إقرار بالتعاطي -وجود سابقتني منها ترويج مخدرات -شهادة غير موصلة -صرف نظر عن ثبوت الترويج -حد املسكر.","document_number":"33347139","case_number":"7881","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1430/12/18","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -إقرار بالتعاطي -وجود سابقتني منها ترويج مخدرات -شهادة غير موصلة -صرف نظر عن ثبوت الترويج -حد املسكر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33347139 :‬تاريخه‪1430/12/18 :‬هـ‬\n                         ‫رقم الدعوى‪7881 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34259609‬تاريخه‪1434/7/4 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬إقــرار بالتعاطــي ‪ -‬وجــود‬\n ‫ســابقتني منهــا ترويــج مخــدرات ‪ -‬شــهادة غيــر موصلــة ‪ -‬صــرف نظــر‬\n                                     ‫عــن ثبــوت الترويــج ‪ -‬حــد املســكر‪.‬‬\n\n\n\n\n ‫املــادة ‪ 194‬مــن نظــام االجــراءات اجلزائيــة واملــادة (‪ )41‬مــن نظــام‬\n                                 ‫مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n ‫أقــام املدعــي العــام دعــوى ضــد املدعــى عليــه لقيامــه بترويــج‬\n ‫اإلمفيتامــن‪ -‬بقصــد الكســب املــادي ‪ -‬حيــث مت القبــض علــى املدعــى‬\n ‫عليــه يف ســيارة املصــدر الســري وبحوزتــه حبــوب اإلمفيتامــن وقــد‬\n ‫أنكــر املدعــى عليــه صفــة الترويــج وأقــر صفــة التعاطــي ومت القبــض‬\n ‫علــى املدعــى عليــه وبحوزتــه اإلمفيتامــن وقــد ضبــط متلبس ـ ًا وأقــر‬\n ‫بصحــة القبــض‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة‬\n ‫املضبوطــة علــى اإلمفيتامــن‪ ،‬طلــب املدعــي العــام باحلكــم علــى املدعى‬\n ‫عليــه بعقوبــة القتــل التعزيريــة ‪ ،‬واحلكــم عليــه بحــد املســكر العترافــه‬\n ‫بتعاطــي احلشــيش املخــدر‪ ،‬ومصــادرة جوالــه املوصــوف بالوقائــع‬\n ‫ومصــادرة شــريحة الهاتــف لنفــس املشــترك وقــد قــررت احملكمــة ثبــوت‬\n\n                                                                                   ‫‪160‬‬\n\f      ‫إدانــة املدعــى عليــه بتعاطــي احلشــيش وحيازتــه ‪ -‬وحكمــت احملكمــة‬\n      ‫بجلــد املدعــى عليــه ثمانــون جلــدة حـ ًـدا وذلــك لتعاطيــه املخــدر‪ ،‬وســجنه‬\n      ‫ســنتني حتســب مــن تاريــخ توقيفــه وذلــك لثبوت حيازته احلبــوب احملظورة‬\n      ‫وعــدم ثبــوت ترويجــه لهــا‪ ،‬واملنــع مــن الســفر خــارج البــاد مــدة ســنتني‬\n      ‫بعــد االنتهــاء مــن مــدة ســجنه واعتــرض املدعــى العــام علــى احلكــم وقنــع‬\n      ‫املدعــى عليــه ‪ -‬وجــرى تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لدينــا نحــن ‪ .......‬القضــاة باحملكمــة العامــة‬\n      ‫بالدمــام بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة الرئيــس برقــم ‪ .......‬يف‬\n      ‫‪ .......‬ه ــفي دعــوى املدعــي العــام ضــد ‪....... /‬و فيهــا افتتحــت اجللســة‬\n      ‫ا بصفتــي مدعيــا عاما بدائــرة اإلدعاء‬        ‫وفيهــا حضــر املدعــي وأدعــى قائـ ً‬\n      ‫العــام لفــرع الهيئــة باملنطقــة الشــرقية ‪.......‬ادعــي علــى ‪ .......‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬ولــه ســوابق األولــى ترويــج‬\n      ‫مخــدرات وقيــادة الســيارة وهــو بحالــة الســكر رقــم احلكــم ‪.......‬‬\n      ‫والثانيــة ســرقة ســيارات وســرقة ســاكن رقــم احلكــم ‪ 2/75‬وحيــث‬\n      ‫باالطــاع علــى محضــر االنتقــال والقبــض والتفتيــش املعــد مــن قبــل‬\n      ‫رجــال مكافحــة املخــدرات تبــن أنــه يف يــوم االثنــن املوافــق ‪.......‬وردهــم‬\n      ‫بــاغ مــن أحــد مصادرهــم الســرية عــن قيــام املتهــم املذكــور أعــاه‬\n      ‫بالتوســط يف إحضــار احلبــوب املنبهــة واحملظــورة واســتعد املصــدر‬\n      ‫لإلحاطــة بــه وضبطــه باجلــرم املشــهود فتــم متكينــه مــن االتصــال علــى‬\n      ‫جــوال املتهــم املذكــور رقــم ‪.......‬مــن نــوع ‪ ....‬رقمــه املصنعــي ‪........‬وطلــب‬\n      ‫منــه كميــة مــن احلبــوب املنبهــة مببلــغ وقــدره مائتــن ريــال فوافــق‬\n\n‫‪161‬‬\n\f‫املذكــور وطلــب مــن املصــدر أن يحضــر إليــه عنــد منزلــه ليذهــب معــه‬\n‫إلحضــار الكميــة املطلوبــة فجــرى تفتيــش املصــدر وتفتيــش ســيارته‬\n‫تفتيشــا دقيقــا وتزويــده مببلــغ مرقــم وقــدره مائتــن ريــال اجتــه املصــدر‬\n‫للموقــع املتفــق عليــه حتــت أنظــار الفرقــة القابضــة إلــى حــي ‪........‬بالقرب‬\n‫مــن الشــرطة الشــمالية وعنــد وصولــه ركــب معــه املذكــور واجتهــا إلــى‬\n‫مخطــط ‪ 8‬وتوقفــا أمــام بوفيــة ‪........‬ونــزل املذكــور ودخــل داخــل احلــي‬\n‫ومتــت متابعتــه اال أنــه اختفــى عــن األنظــار وبعــد قرابــة البيــع بســاعة‬\n‫شــوهد املذكــور وهــو يخــرج مــن احلــي ويركــب مــع املصــدر فأعطــى‬\n‫األخيــر اإلشــارة الدالــة علــى إمتــام البيــع فتــم القبــض عليــه وبتفتيشــه‬\n‫عثــر بجيــب ثوبــه علــى نصــف حبــة اثبــت التقريــر الكيمــاوي الشــرعي‬\n‫رقم‪........‬تاريــخ ‪1430/9/25‬ه ـ ايجابيتهــا للمــادة االمفيتامــن املنبهــة‬\n‫واحملظــورة املــدرج يف اجلــدول الثانــي فئــة ب مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة وقــام املصــدر بتســليم أفــراد الفرقــة‬\n‫القابضــة الكميــة املروجــة وهــي عبــارة عــن ســت حبــات واحــدة منهــا‬\n‫مكســورة نصفــن اثبــت التقريــر الكيمــاوي الشــرعي املشــار إليــه‬\n‫إيجابيتهــا جميعــا كال علــى حــدة ملــادة االمفيتامــن املنبهــة واحملظــورة‬\n‫وباســتجواب املتهــم املذكــور نفــى التهمــة املنســوبة إليــه وأفــاد انــه يف‬\n‫يــوم االثنــن املوافــق ‪1430/9/17‬ه ـ اتصــل بــه املصــدر وطلــب منــه‬\n‫حبــوب منبهــة مببلــغ مائتــن ريــال فطلــب مــن املصــدر أن يحضــر إلــى‬\n‫منزلــه ليذهبــا ســويا ويحضراهــا مــن شــخص يدعــى وعنــد حضــور‬\n‫املصــدر ركــب معــه الســيارة واجتهــا إلــى مخطــط ‪ 8‬واتصــل بــدوره علــى‬\n‫‪ .....‬ولــم يجــده وأثنــاء جتولهمــا شــاهدا شــخص يعرفــه وهــو واملصــدر‬\n‫يدعــى ‪ ....‬فتحــدث معــه املصــدر وطلــب منــه حبــوب منبهــة مببلــغ مائتــن‬\n\n\n                                                                                      ‫‪162‬‬\n\f      ‫ريــال فذهــب وعــاد بعــد خمــس دقائــق واحضــر احلبــوب وســلم املصــدر‬\n      ‫ســبع حبــات منبهــة واســتلم املبلــغ وأثنــاء عودتهمــا قــام املصــدر بإعطائــه‬\n      ‫حبــة منبهــة فابتلــع نصفهــا وأبقــى نصفهــا اآلخــر معــه فتــم مداهمتــه مــن‬\n      ‫قبــل رجــال مكافحــة املخــدرات والقبــض عليــه وبتفتيشــه عثــر بحوزتــه‬\n      ‫علــى نصــف احلبــة احملظــورة وهــي لــه بقصــد التعاطــي وأقــر بتعاطــي‬\n      ‫احلبــوب املنبهــة واحملظــورة منــذ اثنتــي عشــرة ســنة وآخــر مــرة كانــت‬\n      ‫قبــل القبــض عليــه بنصــف ســاعة وبســماع أقوالــه األوليــة أقــر بالتوســط‬\n      ‫يف بيــع احلبــوب واحملظــورة واســتعمال احلشــيش املخــدر يف الســابق‬\n      ‫وانتهــى التحقيــق معــه باتهامــه باآلتــي ‪ /1‬بيــع ‪ 6‬ســت حبــات منهــا واحــدة‬\n      ‫مكســورة نصفــن مــن حبــوب االمفيتامــن املنبهــة واحملظــورة بقصــد‬\n      ‫االجتــار ‪ /2‬حيــازة نصــف حبــة مــن حبوب االمفيتامــن املنبهة واحملظورة‬\n      ‫بقصــد الترويــج والتعاطــي ‪ /3‬توســطه يف بيــع احلبــوب احملظــورة يف‬\n      ‫الســابق ‪ /4‬تعاطــي احلبــوب املنبهــة واحملظــورة واحلشــيش املخــدر وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة ‪ :‬اعترافــه حتقيقــا بصحــة واقعــة القبــض املنــوه‬\n      ‫عنــه املرفــق علــى اللفــات رقــم ‪10‬ـ‪ 12‬مــا ورد يف أقوالــه األوليــة املنــوه‬\n      ‫عنهــا املدونــة علــى الصفحــات رقــم ‪5‬ـ‪ 7‬مــن بلــن التحقيــق ‪ /3‬محضــر‬\n      ‫القبــض والتفتيــش املنــوه عنــه املــدون علــى الصفحــات رقــم ‪2‬ـ‪ 4‬مــن ملــف‬\n      ‫التحقيــق ‪ /4‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة‬\n      ‫رقــم ‪ 15‬وحيــث أن مــا أقــدم عليــه املذكــور وهو بكامــل أهليته املعتبرة‬\n      ‫شــرعا فعــل محــرم ومعاقــب عليــه شــرعا ومجــرم نظامــا مبوجــب نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة يف عقوباتــه األصليــة‬\n      ‫والتكميليــة اطلــب إثبــات إدانتــه مبــا أســند إليــه ومــن الفقــرة رقــم ‪ 2‬مــن‬\n      ‫املــادة رقــم ‪ 3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم‬\n\n\n‫‪163‬‬\n\f‫عليــه بالقتــل تعزيــرا وفقــا للمــادة اخلامســة مــن البنــد األول مــن املــادة‬\n‫رقــم ‪ 37‬مــن النظــام واحلكــم عليــه بحــد املســكر العترافــه بتعاطــي‬\n‫احلشــيش املخــدر ومصــادرة جوالــه املوصــوف بالوقائــع وفقــا للمــادة مــن‬\n‫النظــام ومصــادرة شــريحة الهاتــف وعــدم حذفهــا لنفــس املشــترك وفقــا‬\n‫لتعميــم ســمو النائــب الثانــي وزيــر الداخليــة رقــم ‪ 9798 /‬وتاريــخ ‪9‬ـ‪10‬‬\n‫‪ 1428/2/‬ه ـ أ‪.‬ه ـ ويف هــذه اجللســة حضــر املدعي العــام وحضر حلضوره‬\n‫املدعــى عليه‪.......‬املدونــة هويتــه آنفــا ويحمــل نســبة مــن احلاســب اآللــي‬\n‫ملصقــة عليهــا صورتــه ومصــدق ومختــوم عليهــا مــن شــعبة مكافحــة‬\n‫املخــدرات بالدمــام وبعــد تــاوة الدعــوى عليــه أجــاب قائــا أنــه يف ‪.......‬‬\n‫تصــل علــى ‪.......‬وهــو صديــق لــي وقــال ســوف احضــر إليــك لنذهــب إلــى‬\n‫مخطــط ‪ 8‬وحضــر وركــب معــي ودخلنــا احلــي وشــاهد شــخص يدعــى‬\n‫اعرفــه ويعرفــه أيضــا زميلــي ونزلــت وســلمت عليــه وأصبــح يتحــدث مــع‬\n‫‪ ....‬ثــم رجعــت وركبــت الســيارة وبعــد ذلــك ركــب الســيارة وقــال إننــي‬\n‫أخــذت غــرض مــن ‪ ....‬وأعطانــي حبــة واحــدة منبهــة وقمــت بكســرها‬\n‫نصفــن وأكلــت نصــف واحتفظــت بالنصــف يف جيبــي ثــم خرجنــا مــن‬\n‫احلــي وطلبــت التوقــف عنــد بوفيــه آلخــذ شــاي فقبضــت علينــا املخــدرات‬\n‫وعثــرت معــي علــى نصــف حبــة مــن احلبــوب املنبهــة الكبتاجــون وأنــا لــم‬\n‫أتوســط يف شــراء احلبــوب كمــا ذكــر املدعــي العــام يف دعــواه وســمع‬\n‫ذلــك املدعــي العــام وقــال الصحيــح مــا ذكرتــه ومــا جــاء يف أوراق‬\n‫املعاملــة وأطلــب الرجــوع إليهــا وأضــاف املدعــى عليــه قائــا أننــي‬\n‫اســتعمل احلشــيش املخــدر وآخــر مــرة اســتعملته قبــل القبــض علــي بثالث‬\n‫أشــهر وأنــا علــي ســابقتني األولــى ترويــج مخــدرات والثانية ســرقة ســيارة‬\n‫ويف جلســة أخــرى افتتحــت هــذه اجللســة ويف هــذه اجللســة وبالرجــوع‬\n\n\n                                                                                      ‫‪164‬‬\n\f      ‫ألوراق املعاملــة وجــدة ان حتقيــق مــع املدعــى عليــه علــى اللفــات‬\n      ‫‪10‬و‪11‬و‪ 12‬وقــد جــاء فيهــا اســتجواب املدعــى عليــه علــى مــا يلــي س‪/‬‬\n      ‫أنــت متهــم ببيــع املؤثــرات العقليــة وحيــازة مؤثــرات عقليــة بقصــد‬\n      ‫التعاطــي أو االســتعمال الشــخصي ج‪ /‬غيــر صحيــح س‪/‬اشــرح لنــا‬\n      ‫بالتفصيــل كيــف مت القبــض عليــك ج‪ /‬انــه يف يــوم االثنــن املوافــق‬\n      ‫‪ 1430/9/17‬ه ـ اتصــل بــي (املصــدر) علــى جوالــي رقــم ‪.......‬مــن نــوع ‪....‬‬\n      ‫وطلــب منــي حبــوب منبهــة مببلــغ (‪ )200‬مائتــن ريــال وأخبرتــه أن‬\n      ‫يحضــر إلــى منزلــي لنذهــب ســويا ونحضرهــا مــن شــخص آخــر يدعــى ‪/‬‬\n      ‫‪ .......‬وعنــد حضــوره ركبــت معــه الســيارة واجتهنــا إلــى مخطــط ‪8‬‬\n      ‫واتصلــت علــى ‪ .......‬ولــم أجــده وأثنــاء جتولنــا شــاهدنا شــخص يدعــى ‪....‬‬\n      ‫أعرفــه ويعرفــه املصــدر أيضــا فتحــدث معــه املصــدر وطلــب منــه حبــوب‬\n      ‫منبهــة مببلــغ (‪ )200‬مائتــن ريــال فذهــب وعــادة بعــد خمــس دقائــق‬\n      ‫وأحضــر احلبــوب وســلم املصــدر ســبع حبــات منبهــة واســتلم املبلــغ وأثنــاء‬\n      ‫عودتنــا قــام املصــدر بإعطائــي حبــة منبهــة فابتلعــت نصفهــا وأبقيــت‬\n      ‫نصفهــا اآلخــر معــي فتــم مداهمتنــا مــن قبــل رجــال مكافحــة املخــدرات‬\n      ‫وبتفتيشــي عثــر علــى نصــف حبــة بحوزتــي مــن احلبــوب املنبهــة فتــم‬\n      ‫القبــض علــي ‪ ....‬س‪ /‬ورد يف أقوالــك األوليــة أنــك أنــت واملصــدر‬\n      ‫اشــتريتما احلبــوب املنبهــة مــن املدعــو ‪ .......‬وذكــرت اآلن يف اســتجوابك‬\n      ‫أنكمــا اشــتريتما مــن املدعــو ‪ ....... /‬فمــا قولــك ج‪ /‬الصحيــح أننــا‬\n      ‫اشــتريناهم مــن املدعــو ‪ ......./‬وعندمــا ذكــرت ‪ .......‬يف أقوالــي األوليــة‬\n      ‫كنــت مخطئـ ًا يف األســماء س‪ /‬ورد يف أقوالــك األوليــة انــك تتوســط يف‬\n      ‫بيــع احلبــوب املنبهــة إذا أحرجــك أحــد فكيــف تغيــر قولــك هــذا ج‪/‬‬\n      ‫تعرضــت للضــرب فأجبــرت علــى قــول ذلــك س‪ /‬ورد يف محضــر القبــض‬\n\n\n‫‪165‬‬\n\f‫انــه جــرى االتصــال عليــك مــن قبــل املصــدر وطلــب منــك حبــوب منبهــة‬\n‫مببلــغ (‪ )200‬مائتــي ريــال فطلبــت منــه أن يحضــر إليــك فمــا قولــك ج‪/‬‬\n‫نعــم صحيــح س‪/‬ورد يف محضــر القبــض عليــك أن املصــدر حضــر‬\n‫ملنزلــك وركبــت معــه الســيارة وتوجهتمــا إلــى مخطــط ‪ 8‬فمــا قولــك ج‪/‬‬\n‫نعــم صحيــح س‪ /‬ورد يف محضــر القبــض انــك نزلــت مــن الســيارة‬\n‫ودخلــت داخــل احلــي وبعــد ربــع ســاعة خرجــت مــن احلــي وركبــت مــع‬\n‫املصــدر فمــا قولــك ج‪ /‬هــذا الــكالم غيــر صحيــح حيــث حضــر‬\n‫املدعــو‪ ..........‬واتفــق مــع املصــدر وســلمه احلبــوب ونحــن داخــل الســيارة‬\n‫ويف جلســة أخــرى افتتحــت اجللســة ويف هــذه اجللســة حضــر املدعــي العــام‬\n‫وحضــر حلضــوره املدعــى عليــه وبعــرض مــا جــاء يف التحقيــق على املدعى‬\n‫عليــه أجــاب قائــا إن مــا ورد يف التحقيــق منــه الصحيــح ومنــه غيــر‬\n‫الصحيــح والصحيحــة أن املصــدر صديــق لــي ويتصــل علــي دائمــا واخــرج‬\n‫معــه وقــد اتصــل علــي وطلــب منــي اخلــروج معــه وملــا حضــر ركبــت معــه‬\n‫وذهبنــا ملخطــط ‪8‬وقابــل شــخص اعرفــه ويعرفــه املصــدر وال اذكــر‬\n‫اســمه الصحيــح هــل هــو ‪ .......‬أو ‪ .......‬ألنــه كان يســكن يف حارتنــا‬\n‫القدميــة مخطــط ‪ 8‬وســلمت عليــه ورجعــت وركبــت الســيارة وحتــدث‬\n‫معــه املصــدر وال اعلــم مــا دار بينهمــا ولــو كنــت مروجــا ملــا أعطانــي‬\n‫حبــة والتــي أكلــت نصفهــا واحتفظــت بالنصــف اآلخــر واملصــدر قــد‬\n‫حصــل علــى احلبــوب مــن الرجــل الــذي قابلــه يف مخطــط ‪ 8‬وأنــا ال أعــرف‬\n‫اســمه هــل هــو أو هكــذا أجــاب لــذا ويف جلســة أخــرى افتتحــت اجللســة‬\n‫وبالرجــوع ألوراق املعاملــة وجــد محضــر انتقــال وقبــض تفتيــش بتاريــخ‬\n‫‪.......‬ه ـ علــى ملــف التحقيــق الصفحــة ‪3‬و‪ 4‬وهــذا نصــه ( احلمــد هلل‬\n‫والصــاة والســام علــى رســول اهلل وبعــد ‪....‬نثبــت نحــن املوقعــن أدنــاه‬\n\n\n                                                                                    ‫‪166‬‬\n\f      ‫وبتاريخــه أعــاه وبنــاء علــى البــاغ املــدون بالصفحــة رقــم ‪ 2‬مــن ملــف‬\n      ‫االســتدالل مت االجتمــاع بالفرقــة واملصــدر وإلــى الســاعة العاشــرة‬\n      ‫‪25863‬مســاء وأفهــم كل عضــو بالفرقــة بــدوره ومت متكــن املصــدر مــن‬\n      ‫االتصــال علــى الوســيط وطلــب منــه كميــة مــن احلبــوب احملظــورة مببلــغ‬\n      ‫مالــي وقــدره مائتــي ريــال فوافــق الوســيط علــى ذلــك وطلــب مــن املصــدر‬\n      ‫أن يحضــر إليــه عنــد منزلــه بالدمــام حــي ‪........‬لنصــب مــع املصــدر‬\n      ‫إلحضــار الكميــة املطلوبــة وعلــى الفــور مت تفتيــش املصــدر وســيارته‬\n      ‫تفتيشــا دقيقــا إبــراء للذمــة ومت تزويــده مببلــغ حكومــي وقــدره مائتــي‬\n      ‫ريــال بعــد أن مت ترقيمهــا علــى النحــو التالــي ‪ /‬فئــة مائــة ريــال (‪(،)........‬‬\n      ‫‪ )........‬وبعدهــا أمــر قائــد الفرقــة املصــدر باالنتقــال إلــى مــكان تواجــد‬\n      ‫الوســيط وبالفعــل اجتــه املصــدر حتــت أنظــار الفرقــة إلــى حــي ‪........‬‬\n      ‫بالقــرب مــن الشــرطة الشــمالية واحتــك معــه شــخص وركــب معــه‬\n      ‫واجتهــا بجهــة مخطــط ‪ 8‬وتوقفــوا أمــام بوفيــة ‪ ....‬مبخطــط ‪ 8‬علــى شــارع‬\n      ‫‪........‬ونــزل الوســيط ودخــل داخــل احلــي ومتــت متابعتــه إال انــه اختفــى عــن‬\n      ‫األنظــار وبعــد قرابــة الربــع ســاعة شــوهد الوســيط وهــو يخــرج مــن احلــي‬\n      ‫وركــب مــع املصــدر بعدمــا أعطــى املصــدر اإلشــارة الدالــة علــى عمليــة‬\n      ‫الترويــج وعلــى الفــور مت ضبــط الوســيط و اتضــح أنــه يدعــى‪....... /‬‬\n      ‫ســعودي اجلنســية وبتفتيشــه شــخصيا عثــر بجيبــه علــى نصــف حبــة‬\n      ‫يشــتبه أن تكــون مــن حبــوب الكبتاجــون واحملظــورة ‪ ،‬ومبســائلته عــن‬\n      ‫مصــدر مــا ضبــط بحوزتــه ومــا قــام بفعلــه مــن توســط ترويــج احلبــوب‬\n      ‫احملظــورة أنكــر قيامــه بشــيء بتاتــا‪ ،‬علمــا أن املصــدر قــام بتســليمه‬\n      ‫الكميــة املروجــة للوكيــل رقيــب ‪.......‬وهــي عبــارة عنــة عدد ســت حبات‬\n      ‫واحــدة منهــا مكســورة نصفــن حتمــل عالمــة القوســن يشــتبه أن‬\n\n\n‫‪167‬‬\n\f‫تكــون مــن حبــوب الكبتاجــون احملظــورة ‪ ،‬علمــا أن جــوال الوســيط‬\n‫مــن نــوع ‪ ....‬ورقــم الكــود ‪ ......‬بعدهــا مت اصطحــاب املذكــور ومــا‬\n‫ضبــط بحوزتــه ملقــر شــعبة مكافحــة املخــدرات بالدمــام متهيــدا إلعــداد‬\n‫احملضــر الــازم وحفظــا للواقــع ‪ ،‬ثــم إعــداده والتوقيــع عليــه واهلل املوفــق‬\n‫الفرقــة القابضــة جنــدي ‪ .......‬قائــد الفرقــة القابضــة رئيــس رقبــاء ‪،.......‬‬\n‫وســوف يتــم طلــب الفرقــة القابضة ويف يوم األحــد املوافق‪1433/04/11‬‬\n‫ه ـ لدينــا نحــن ‪ ..........‬القضــاة اخللــف باحملكمة العامــة بالدمام افتتحت‬\n‫اجللســة وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه ‪.......‬‬\n‫وجــرى قــراءة مــا ســبق ضبطــه علــى املدعــى عليــه فصــادق عليــه ونظــر ًا‬\n‫الســتدعاء احلــال فســيجري اســتدعاء الفرقــة القابضــة ألخــذ مــا لديهــم‬\n‫وهــم كال مــن اجلنــدي ‪ .......‬ويف يوماألحداملوافــق‪ 1433/05/02‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪11 : 01‬وفيهــا حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليــه ‪.......‬وحضــر مــن الفرقــة القابضــة كال مــن ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬و ‪.......‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬وبســؤال ‪ ....‬عمــا لديــه مــن‬\n‫شــهادة قــال لقــد مضــى علــى هــذه القضيــة مــدة ثــاث ســنوات تقريب ـ ًا‬\n‫وقــد نســيت كثيــر مــن تفاصيلهــا لذلــك فأنــه ليس لدي شــهادة وبســؤال‬\n‫‪.......‬قــال ال أذكــر كثيــر مــن تفاصيــل هــذه القضيــة فليــس عنــدي‬\n‫شــهادة بنــاء عليــه فقــد رفعــت اجللســة مــع إفهــام املدعــي العــام بإحضــار‬\n‫بقيــة أعضــاء الفرقــة القابضــة وهــم كال مــن ‪.......‬و ‪.......‬ويف يــوم األحــد‬\n‫املوافــق‪ 1433/05/23‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 58‬وفيهــا حضر‬\n‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه وبســؤاله عــن الفرقــة‬\n‫القابضــة قــال لقــد تعــذر إحضــار أعضــاء الفرقــة القابضــة وهــم كل‬\n\n\n                                                                                      ‫‪168‬‬\n\f      ‫مــن ‪.......‬واطلــب إمهالنــا خمســة عشــر يوم ـ ًا نظــر ًا لتمتــع أحــد أعضــاء‬\n      ‫الفرقــة بإجــازة ويف يــوم األحــد املوافق‪ 1433/06/22‬هـ افتتحت اجللســة‬\n      ‫الســاعة ‪11 : 41‬وفيهــا حضــر املدعــى عليــه الســجني ‪ .......‬ولــم يحضــر‬\n      ‫املدعــي العــام وال الفرقــة القابضــة ويف يــوم الثالثــاء املوافــق‬\n      ‫‪1433/07/01‬ه ـ افتتحــت اجللســة الســاعة ‪ 11:00‬وفيهــا حضــر‬\n      ‫الســجني‪.......‬ولم يحضــر املدعــي العــام وال الفرقــة القابضــة ويف يــوم‬\n      ‫الثالثــاء املوافــق ‪ 1433/07/08‬ه ـ افتتحــت اجللســة الســاعة وفيهــا‬\n      ‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه ‪.......‬ولــم يحضــر‬\n      ‫ـاء علــى الدعــوى واإلجابــة وجميــع مــا‬ ‫املدعــي العــام بينتــه علــى دعــواه فبنـ ً‬\n      ‫تقــدم ونظــر ًا لكــون املدعــي العــام احضــر اثنــن مــن الفرقــة القابضــة‬\n      ‫وباســتجوابهما أنكــرا معرفتهمــا بالواقعــة ثــم عجــز املدعــي العــام عــن‬\n      ‫إحضــار بقيــة أعضــاء الفرقــة القابضــة مــع إمهالــه عــدة جلســات‬\n      ‫إلحضارهــم عليــه فقــد صرفنــا النظــر عمــا جــاء يف دعــوى املدعــي العــام‬\n      ‫مــن اتهامــه للمدعــى عليــه يف قيامــه بترويــج احلبــوب احملظــورة بقصــد‬\n      ‫االجتــار وقررنــا مــا يلــي أوال جلــد املدعــى عليــه ‪.......‬ثمانــون جلــده حــد ًا‬\n      ‫وذلــك لتعاطيــه احلشــيش املخــدر ثاني ـ ًا ســجنه مــدة ســنتني حتســب مــن‬\n      ‫تاريــخ توقيفــه وذلــك حليازتــه احلبــوب احملظــورة حســب املــادة ‪ 41‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ثالث ـ ًا منعــه مــن الســفر‬\n      ‫إلــى خــارج اململكــة مــدة ســنتني بعــد انتهــاء تنفيــذ عقوبــة الســجن وبــه‬\n      ‫حكمنــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه‬\n      ‫باحلكــم أمــا املدعــي العــام قــرر عــدم قناعتــه وجــرى إفهامــه مبراجعــة‬\n      ‫احملكمــة خــال عشــرة أيــام الســتالم نســخة مــن احلكــم ثــم تقــدمي‬\n      ‫الئحــة االعتراضيــة وافهــم مبقتضــى املــادة ‪ 194‬مــن نظــام اإلجــراءات‬\n\n\n‫‪169‬‬\n\f‫اجلزائيــة وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                      ‫وصحبه وسلم ‪ .‬حرر ‪.......‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/02/26‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪12:45‬وقــد جــرى رفــع املعاملــة الــى محكمــة‬\n‫االســتئناف وأعيــدت لنــا مــن فضيلــة الرئيــس وقيــدت باحملكمــة برقــم‬\n‫‪ .......‬يف ‪.......‬شــرحا علــى خطــاب معالــي رئــي محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية رقــم ‪ .......‬يف ‪1434/1/25‬ه ـ مرفقــا بهــا القــرار‬\n‫الصــادر مــن أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة اخلماســية‬\n‫االولــى يف محكمــة االســتئناف باملنطقــة الشــرقية برقــم ‪ .......‬يف ‪.......‬‬\n‫املتضمــن مــا نصــه (أن أصحــاب الفضيلــة لــم يقــرروا اإلدانــة باحليــازة‬\n‫قبــل تقريــر العقوبــة ملالحظــة مــا ذكــر ومــن ثــم إعــادة املعاملــة) أ‪.‬ه ـ‬\n‫فنقــول جوابــا ألصحــاب الفضيلــة بأنــه ثبــت لدينــا حيــازة املدعــى عليــه‬\n‫للحبــوب احملظــورة وســيجري بعــث املعاملــة الــى محكمــة االســتئناف‬\n‫إلكمــال الزمهــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪.......‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام‬\n‫برقــم ‪.......‬وتاريــخ ‪ .......‬واملقيــدة لــدى احملكمــة برقــم ‪.......‬وتاريــخ‬\n‫‪.......‬املرفــق بهــا القــرار الشــرعي ذو الرقــم ‪ .......‬والتاريــخ ‪.......‬الصــادر‬\n‫مــن أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪ ......./‬يف قضيــة‬\n‫مخــدرات وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق‬\n\n\n                                                                                        ‫‪170‬‬\n\f      ‫املعاملــة وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة علــى قرارنــا‬\n      ‫رقــم ‪ .......‬وتاريــخ ‪.......‬وقرارنــا رقــم ‪ .......‬وتاريــخ ‪.......‬ه ـ قررنــا املصادقــة‬\n      ‫علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                       ‫محمــد وآلــه وصحبــه وســلم حــرر يف ‪ 1434/7/4‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n‫‪171‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":160,"source_page_end":171,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"30e38885e5ed045f2162833bb5d8a6e9d2b2ace950bccfee8b43e731a5372da4","normalized_text_hash":"2bf7f1875e4b772b9caae58db7d7402d92ac1aca65d1c9468554ef6ce59dac13","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p160-33347139"},{"id":"33ec8138-6672-527f-8f3e-d4abda473c67","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -مخدرات -حيازة مسكر وحشيش وحبوب محظورة بقصد االجتار والتعاطي -حد املسكر -تعزير بالسجن واجللد والغرامة واملنع من السفر.","document_number":"34176202","case_number":"34266","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/1","year":"1434","subject":"مسكر -مخدرات -حيازة مسكر وحشيش وحبوب محظورة بقصد االجتار والتعاطي -حد املسكر -تعزير بالسجن واجللد والغرامة واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34176202 :‬تاريخه ‪1434/04/1 :‬هـ‬\n                       ‫رقم الدعوى ‪34266 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34257252‬تاريخه‪1434/7/2 :‬هـ‬\n\n\n ‫مســكر ‪ -‬مخــدرات ‪ -‬حيــازة مســكر وحشــيش وحبــوب محظــورة بقصــد‬\n ‫االجتــار والتعاطــي ‪ -‬حــد املســكر ‪ -‬تعزيــر بالســجن واجللــد والغرامــة‬\n                                                        ‫واملنــع مــن الســفر‪.‬‬\n\n\n\n\n ‫‪ -1‬قــال ابــن قدامــه رحمــه اهلل يف املغنــي (‪ ( :)59/5‬وال يقبــل رجــوع املقــر‬\n ‫عــن إقــراره إال فيمــا كان حــد ًا هلل تعالــى يــدرأ بالشــبهات ويحتــاط‬\n ‫إلســقاطه فأمــا حقــوق اآلدميــن وحقــوق اهلل تعالــى التــي ال تــدرأ‬\n ‫بالشــبهات كالــزكاة والكفــارات فــا يقبــل رجوعــه عنهــا وال نعلــم يف‬\n                                                                ‫ذلــك خالف ـ ًا ) ‪.‬‬\n ‫‪ -2‬لعــن رســول اهلل صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ‪ ( :‬شــاربها‬\n ‫وســاقيها وحاملهــا واحملمولــة إليــه وعاصرهــا ومعتصرهــا وبائعهــا‬\n                                                                ‫وآكل ثمنهــا ) ‪.‬‬\n ‫‪ -3‬قــال ابــن حجــر رحمــه اهلل يف فتــح البــاري (‪ ( : )45/10‬واســتدل‬\n ‫مبطلــق قولــه صلــى اهلل عليــه وســلم ( كل مســكر حــرام ) علــى حتــرمي‬\n ‫مــا يســكر ولــو لــم يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــه وغيرهــا وقــد‬\n                                      ‫جــزم النــووي وغيــره بأنهــا مســكرة ) ‪.‬‬\n ‫‪ -4‬املــواد (‪ )38‬و (‪ )41‬و (‪ )56‬و (‪ )62‬مــن نظــام مكافحــة املخــدرات‬\n                                                           ‫واملؤثــرات العقليــة‪.‬‬\n\n\n                                                                                      ‫‪172‬‬\n\f      ‫توجيــه االتهــام للمدعــى عليــه بالشــروع ببيــع جــزء مــن احلشــيش املخــدر‬\n      ‫‪ -‬حيــازة قطــع متفاوتــة مــن احلشــيش بقصــد الترويــج والتعاطــي وحيــازة‬\n      ‫(‪ )3211‬حبــة مــن حبــوب اإلمفيتامــن املنبهــة احملظــورة بقصــد الترويــج‬\n      ‫وتعاطــي حبــوب اإلمفيتامــن وبيع حبوب اإلمفيتامني وحيازة كســر من‬\n      ‫حبــوب اإلمفيتامــن بقصــد الترويــج وحيــازة حبتــن مــن حبــوب الــروش‬\n      ‫بقصــد الترويــج وحيــازة (‪ )13‬قــارورة خمــر خارجــي نــوع فــودكا بقصد‬\n      ‫الشــرب والترويــج وشــرب املســكر وتعاطــي احلشــيش املخــدرة ‪ -‬حيــث‬\n      ‫أنــه وردت معلومــات مــن أحــد املصــادر الســرية ملكافحــة املخــدرات عــن‬\n      ‫املدعــى عليــه بــأن لــه نشــاط واســع يف ترويــج املخــدرات ومــن أربــاب‬\n      ‫الســوابق ويســتخدم اجلــوال يف ذلــك ويســتخدم ســيارة ويســتأجر أجنحــة‬\n      ‫ببعــض الفنــادق الفارهــة إلبعــاد الشــكوك عنــه ‪ -‬مت وضــع الشــخص‬\n      ‫حتــت املراقبــة ‪ -‬شــوهد يتــردد علــى فنــدق ويســكن فيــه ويتــردد عليــه‬\n      ‫أشــخاص معروفــن لــدى مكافحــة املخــدرات ممــا يؤكــد تعاملــه‬\n      ‫بترويــج املخــدرات ‪ -‬مت متكــن املصــدر مــن مراســلة املدعــى عليــه ‪-‬‬\n      ‫أرســل املصــدر للمدعــى عليــه رمــز متعــارف عليــه بينهــم‪ -‬رد املدعــى‬\n      ‫عليــه بوجــود أغــراض جديــدة وأرســل صورتهــا وهــي عبــارة عــن مغلفــن‬\n      ‫ملــادة احلشــيش وذكــر لــه قيمــة الكيلــو مــن احلشــيش ‪ -‬جــرى التنســيق‬\n      ‫مــع مديــر الفنــدق وتفتيــش املصــدر وتزويــده باملبلــغ احلكومــي وحتــرك‬\n      ‫حتــت أنظــار الفرقــة ‪ -‬بدراســة الوضــع للســيطرة علــى املدعــى عليــه‬\n      ‫اتضــح أنــه يحتمــل أن يشــاهد الفرقــة وعلــى الفــور وبطريقــة ســرية مت‬\n      ‫الدخــول علــى املدعــى عليــه والســيطرة عليــه وكان يرافقــه شــخص‬\n\n‫‪173‬‬\n\f‫آخــر وعثــر علــى حقيبــة قماشــية أمــام املدعــى عليــه بهــا كميــة مــن‬\n‫احلشــيش كمــا عثــر علــى عــدد كبيــر مــن احلبــوب احملظــورة وحبتــن‬\n‫مــن حبــوب الــروش وزجاجتــن خمــر وبتفتيــش ســيارته عثــر بهــا علــى‬\n‫صنــدوق بــه قواريــر خمــر خارجــي كمــا ضبــط معــه علــى مبلــغ مالــي‬\n‫كمــا عثــر بنفــس احلقيبــة علــى أوراق مكتــوب عليهــا أرقــام وأســماء‬\n‫أشــخاص ومبالــغ هائلــة وكميــات كبيــرة توضــح تعامــل املدعــى عليــه‬\n‫بترويــج وتصريــف املــواد املخــدرة بكميــات كبيــرة كمــا ضبــط‬\n‫علــى مبلــغ مالــي كبيــر بحــوزة مرافقــه وأفــاد املدعــى عليــه أن هــذا‬\n‫املبلــغ نــاجت عــن ترويــج احلبــوب‪ -‬طلــب املدعــي العــام إثبــات مــا أســند‬\n‫للمدعــى عليــه واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة وتشــديد‬\n‫العقوبــة واملنــع مــن الســفر ومصــادرة الســيارة علــى ضــوء مــا جــاء يف‬\n‫نظــام مكافحــة املخــدرات والؤثــرات العقليــة وتعاميــم وزارة الداخليــة‪-‬‬\n‫كمــا طلــب املدعــي العــام احلكــم علــى املدعــى عليــه بحــد املســكر‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة لقــاء حيــازة املســكر بقصــد الترويــج‬\n‫والشــرب‪ -‬أقــر املدعــى عليــه مبــا ُنســب إليــه ودفــع بــأن قصــده مــن‬\n‫احليــازة االســتعمال الشــخصي‪ -‬حضــر شــاهدان مــن أعضــاء الفرقــة‬\n‫القابضــة‪ -‬بعــد رصــد الشــهادة والرجــوع حملضــر التحريــر والتقريــر‬\n‫الكيميائــي الشــرعي صــدر احلكــم بإثبــات إدانــة املدعــى عليــه بحيــازة‬\n‫كميــة احلشــيش املذكــورة يف الدعــوى بقصــد االســتعمال والترويــج‬\n‫وحبــوب االمفيتامــن املذكــورة عددهــا يف الدعــوى بقصــد االســتعمال‬\n‫والترويــج وبيــع احلشــيش املخــدر واحلبــوب احملظــورة وحيــازة املدعى عليه‬\n‫لقواريــر اخلمــر املذكــورة يف الدعــوى بقصــد الشــرب‪ -‬لــم يثبــت قصــد‬\n‫الترويــج مــن حيــازة اخلمــر ‪ -‬ثبــوت شــرب املدعــى عليه للخمر واســتعماله‬\n\n\n                                                                                    ‫‪174‬‬\n\f      ‫للحشــيش املخــدر واســتعماله حلبــوب االمفيتامــن احملظــورة ‪ -‬إقامــة‬\n      ‫حــد املســكر علــى املدعــى عليــه بجلــده ثمانــن جلــدة‪ -‬تعزيــره بالســجن‬\n      ‫واجللــد والغرامــة واملنــع مــن الســفر‪ -‬صــرف النظــر عــن طلــب املدعــي‬\n      ‫العــام يف مصــادرة ســيارة املدعــى عليــه وجهــاز جوالــه وشــريحته واملبلــغ‬\n         ‫املالــي املضبــوط بحوزتــه‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد لــدي أنــا‬\n      ‫‪ ..‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم وتاريــخ‬\n      ‫‪ 1434/01/03‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/01/03‬‬\n      ‫ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/03/23‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 09 : 40‬وفيهــا قــدم املدعــي العــام ‪ ..‬الئحــة دعــوى عامــه ضــد ‪...‬‬\n      ‫ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ...‬فيهــا حيــث أنــه باالطــاع علــى‬\n      ‫محضــر البــاغ املعــد مــن قبــل مكافحــة املخــدرات بالدمــام بتاريــخ‬\n      ‫‪1433/10/7‬ه ـ املتضمــن انــه بنــاء علــى املعلومــات الــواردة مــن أحــد‬\n      ‫املصــادر الســرية والتــي مفادهــا وجــود شــخص يدعــى ‪ ...‬مــن ســكان‬\n      ‫حــي ‪ ........‬ومــن أربــاب الســوابق يف قضايــا املخــدرات ولــه نشــاط واســع‬\n      ‫يف الترويــج ومــن احلذريــن ويســتخدم اجلــوال رقم(‪)...‬وبقيادتــه ســيارة‬\n      ‫مــن نــوع (‪ )......‬حتمــل اللوحــة رقــم (‪ )...‬ويقــوم باســتئجار أجنحــة ببعــض‬\n      ‫الفنــادق الفارهــة إلبعــاد الشــكوك عنــه وممارســة نشــاط الترويــج‬\n      ‫وباالطــاع علــى احملضــر املتضمن وضع الشــخص حتت املراقبة الســرية‬\n\n‫‪175‬‬\n\f‫وشــوهد يتــردد علــى فنــدق (‪ )........‬واتضــح أنــه يســكن بالــدور (‪)......‬‬\n‫جنــاح رقــم (‪ ).....‬وكان يتــردد عليــه أشــخاص مشــبوهني ومعروفــن‬\n‫لــدى مكافحــة املخــدرات ممــا يؤكــد تعاملــه بترويــج املخــدرات‬\n‫وباالطــاع علــى محضــر االتصــال املعــد مــن قبــل مكافحــة املخــدرات‬\n‫بالدمــام بتاريــخ ‪1433/10/7‬ه ـ املتضمــن انه مت متكني املصدر الســري‬\n‫وباالطــاع مــن رجــال الضبــط للتواصــل معــه عــن طريــق برنامــج (‪)......‬‬\n‫حيــث أرســل املصــدر لــه رمــز متعــارف عليــه بينهــم وهــو (هتك)فــرد عليه‬\n‫املدعــى عليــه موجــود أغــراض جديــدة وأرســل صورتهــا وهــي عبــارة عــن‬\n‫مغلفــن ملــادة احلشــيش وذكــر أن قيمــة الكيلــو اثنــا عشــر ألــف وخمــس‬\n‫مئــة ريــال فوافــق املصــدر وباإلطــاع علــى محضــر القبــض املعــد مــن‬\n‫قبــل مكافحــة املخــدرات بالدمــام املتضمــن انــه بتاريــخ ‪1433/10/7‬ه ـ‬\n‫وبعــد التواصــل بــن املصــدر الســري واملدعــى عليــه عــن طريــق برنامــج‬\n‫(‪ )......‬وافــق املصــدر وكانــت طريقــة املدعــى عليــه أن يقــوم باســتضافة‬\n‫املشــتري عنــده بالفنــدق ويقــوم بإرســال أحــد أعوانــه الغيــر معروفــن‬\n‫للمشــتري ملراقبــة الوضــع يف اخلــارج وجــرى التنســيق مــع مديــر الفنــدق‬\n‫ملعرفــة مــن يتواجــد مــع املدعــى عليــه واتضــح أنــه يســكن بالــدور (‪)......‬‬\n‫غرفــه رقــم (‪ ).....‬ويتــردد عليــه بعــض األشــخاص ومت تزويــد املصــدر‬\n‫باملبلــغ احلكومــي املرقــم وتفتيشــه وحتــرك حتــت أنظــار الفرقــة إلــى‬\n‫أن وصــل إلــى املوقــع احملــدد يف الفنــدق وبدراســة الوضــع للســيطرة‬\n‫علــى املدعــى عليــه اتضــح انــه يحتمــل أن يشــاهد الفرقــة حــن دخولهــا‬\n‫للموقــع وخشــية مــن ضيــاع املبلــغ احلكومــي جــرى مراســلة املدعــى عليــه‬\n‫عــن طريــق (‪ )....‬وذكــر بــأن الكميــة موجــودة لديــه ولكنــه ال بــد مــن‬\n‫تســليم املبلــغ ألحــد أعوانــه ومت علــى الفــور وبطريقــة ســريه الدخــول‬\n\n\n                                                                                     ‫‪176‬‬\n\f      ‫علــى املدعــى عليــه والســيطرة عليــه وكان يرافقــه املدعــو ‪ ...‬وعثــر‬\n      ‫علــى حقيبــة قماشــية أمــام املدعــى عليــه وبهــا ثمانيــة قطــع ســمراء اللــون‬\n      ‫متفاوتــة األحجــام بلــغ وزنهــا جميعــا ‪693.7‬ســتمائة وثالثــة وتســعون‬\n      ‫جرامــا وســبعة مــن العشــرة مــن اجلــرام كمــا عثــر أيضا على عــدد ‪3211‬‬\n      ‫ثالثــة االف ومائتــن واحــدى عشــر حبــة مــن احلبوب احملظــورة ومجموعة‬\n      ‫محظــورة مكســرة تــزن ‪11.3‬احــدى عشــر جــرام وثالثــة مــن العشــرة‬\n      ‫مــن اجلــرام وعدد(‪)2‬حبتــن مــن حبــوب الــروش احملظــورة وزجاجتــن‬\n      ‫خمــر خارجــي نــوع فــودكا وبتفتيــش ســيارته عثــر بهــا علــى كرتــون‬\n      ‫بداخله(‪)11‬احــدى عشــرة قــارورة خمــر خارجــي نــوع فــودكا كمــا‬\n      ‫ضبــط معــه مبلــغ وقدره(‪)3567‬ثالثــة االف وخمســمائة وســبعة وســتون‬\n      ‫ريــال فقــط ال غيــر وأفــاد بصحــة واقعــة الترويــج وأن املبلــغ املضبــوط‬\n      ‫مــع رفيقــه ‪ ..‬هــو نــاجت عــن ترويــج احلبــوب وبتفتيــش ســيارة رفيقــه ‪..‬‬\n      ‫لــم يعثــر علــى شــيء وعثــر بنفــس احلقيبــة علــى أوراق مكتــوب عليهــا‬\n      ‫أرقــام وأســماء أشــخاص ومبالــغ هائلــة وكميــات كبيــرة توضــح تعامــل‬\n      ‫املدعــى عليــه بترويــج وتصريــف املــواد املخــدرة بكميــات كبيــرة كمــا‬\n      ‫ضبــط مــع رفيقــه ‪ ..........‬مبلــغ وقــدره (‪ )20833‬عشــرون ألفــا وثمامنائــة‬\n      ‫وثالثــة وثالثــون ريــال فقــط ال غير وورد تقرير الكيماوي الشــرعي رقم‬\n      ‫‪3640‬ك ش وتاريخ‪1433/10/17‬ه ـ املتضمــن ثبــوت إيجابيــة العينــات‬\n      ‫املضبوطــة ملــادة االمفيتامــن املنبهــة واحملظــورة واملدرجــة يف اجلــدول‬\n      ‫الثانــي فئة(ب)واملرفــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫كمــا تضمــن أيضــا إيجابيــة العينــات املضبوطــة ملــادة احلشــيش املخــدرة‬\n      ‫واحملظــورة واملدرجــة يف اجلــدول األول فئة(أ)واملرفــق بنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة كمــا تضمــن إيجابيــة عينــات املســكر‬\n\n\n‫‪177‬‬\n\f‫ملــادة الكحــول اإليثيلــي وبنســبة مســكرة مت فــرز أوراق مســتقل‬\n‫للمتهــم ‪ ...‬الختــاف مقــر إقامتــه وإحالتهــا لدائــرة التحقيــق واإلدعــاء‬\n‫العــام مبحافظــة النعيريــة إلقامــة الدعــوى العامــة عليــه هنــاك مبوجــب‬\n‫اخلطــاب رقــم ‪1433/11/‬ه ـ وباســتجواب املدعــى عليــه أقــر بحيازتــه ملا‬\n‫مت ضبطــه مــن حبــوب وحشــيش وقواريــر خمــر بقصــد التعاطــي وليــس‬\n‫بقصــد الترويــج وأنكــر علــم مرافقــه بهــا وانتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام ل ـ ‪ ....‬بالشــروع ببيــع جــزء مــن احلشــيش املخــدر وحيازتــه قطــع‬\n‫متفاوتــة األحجــام مــن احلشــيش املخــدر بلــغ إجمالــي وزنهــا (‪)693.7‬‬\n‫ســتمائة وثالثــة وتســعون جرام ـ ًا وســبعة مــن العشــرة مــن اجلــرام بقصــد‬\n‫الترويــج والتعاطــي وحيــازة عــدد (‪ )3211‬ثالثــة آالف ومائتــن وإحــدى‬\n‫عشــرة حبــة مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد الترويــج‬\n‫وتعاطــي نوعهــا وقيامــه ببيــع احلبــوب يف الســابق وحيــازة مجموعــة‬\n‫كســر حبــوب مــن حبــوب االمفيتامــن املنبهــة واحملظــورة وبلــغ إجمالــي‬\n‫وزنهــا (‪ )11.3‬إحــدى عشــر جــرام وثالثــة مــن العشــرة مــن اجلــرام بقصــد‬\n‫الترويــج وحيــازة عدد(‪)2‬حبتــن مــن حبــوب الــروش بقصــد الترويــج‬\n‫وحيــازة عدد(‪)13‬ثالثــة عشــر قــارورة خمــر خارجــي نــوع فــودكا بقصــد‬\n‫الشــرب والترويــج وشــرب املتهــم ‪ ..‬املســكر وتعاطــي احلشــيش املخــدر‬\n‫وذلــك ألدلــة والقرائــن التاليــة ‪ -1‬إقــراره حتقيق ـ ًا املنــوه عنــه واملــدون‬\n‫علــى الصفحــة رقــم (‪ )1.2.3‬واملرفــق لفــه رقــم (‪ -2 )19.18.17‬إقــراره‬\n‫بتعاطــي احلشــيش وشــرب املســكر مبحضــر ســماع األقــوال األوليــة‬\n    ‫املنــوه عنــه واملــدون علــى الصفحــة رقــم(‪ )21‬واملرفــق لفــه رقــم (‪. )1‬‬\n‫‪ -3‬مــا ورد يف محضــر البــاغ املنــوه عنــه مبحضــر االســتدالل واملــدون‬\n‫علــى الصفحــة رقم(‪)2‬واملرفــق لفــه رقم(‪-4)1‬مــا ورد يف محضــر القبض‬\n\n\n                                                                                      ‫‪178‬‬\n\f      ‫مــن وقائــع املنــوه عنهــا واملدونــة علــى الصفحــة رقم(‪)12.13.14‬واملرفقــة‬\n      ‫لفــة رقــم (‪-5)1‬مــا ورد يف محضــر االتصــال املنــوه واملــدون على الصفحة‬\n      ‫رقم(‪)4‬واملرفقــة لفــه رقم(‪-6)1‬مــا ورد يف محضــر املراقبــة الســرية‬\n      ‫املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )3‬مرفــق لفــه رقــم (‪-7)1‬مــا‬\n      ‫ورد يف التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــه رقــم (‪)46‬‬\n      ‫وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه علــى ســابقتني األولــى حيــازة‬\n      ‫واســتعمال املخــدرات والثانيــة حيــازة املخــدرات واســتعمال املخــدرات‬\n      ‫وترويــج مخــدرات وهــروب مــن الســلطة ومقاومــة رجــال األمــن وصــدم‬\n      ‫ســيارة وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب احلكــم‬\n      ‫عليــه مبــا يلــي أو ًال بإثبــات مــا أســند إليــه وفقـ ًا للفقــرة رقم(‪)2‬مــن املــادة‬\n      ‫رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم‬\n      ‫عليــه مبــا يلي‪-1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم‬\n      ‫(‪ )1‬مــن املــادة رقــم(‪ )38‬مــن النظــام مــع مراعــاة مقتضــى املــادة ‪ 62‬مــن‬\n      ‫ذات النظــام وتشــديد العقوبــة عليــه لقيامــه ببيــع احلبــوب احملظــورة‬\n      ‫وتشــديد العقوبــة عليــه لترويجــه حبــوب االمفيتامــن املنبــه واحملظــورة‬\n      ‫وفقـ ًا للفقــرة ‪/2‬ج مــن املــادة ‪38‬م ذات النظــام اســتنادا لبرقيــة ســمو وزير‬\n      ‫الداخليــة رقــم(‪2/8346/4/5/1‬ش) وتاريــخ ‪1427/2/8‬ه ـ ‪-2‬منعــه‬\n      ‫مــن الســفر إعمــاال ملقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن‬\n      ‫النظــام ثاني ـ ًا مصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه ورقمــه‬\n      ‫املصنعــي ‪ .......‬ويحمــل الرقم(‪)..‬الســتخدامه يف الترويــج وفقــا للفقــرة‬\n      ‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام مــع املطالبــة بإســقاط شــريحة‬\n      ‫الهاتــف النقــال وعــدم صرفهــا لنفــس املدعــى عليــه وفقــا لتعميــم ســمو‬\n\n\n‫‪179‬‬\n\f‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريخ‪1429/2/10-9‬ه ـ ثالث ـ ًا احلكــم‬\n‫مبصــادرة األمــوال املضبوطــة مــع املدعــى عليــه وهــو مبلــغ ‪ 3567‬ثالثــة‬\n‫االف وخمســمائة وســبعة وســتون ريــال فقــط ال غيــر لكــون القرائــن‬\n‫واألدلــة املذكــورة ســابق ًا تفيــد أنهــا ناجتــة عــن بيــع املخــدرات وفق ـ ًا‬\n‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام رابعـ ًا مصــادرة الســيارة‬\n‫املســتخدمة يف عمليــة الترويــج نــوع (‪ ).....‬موديــل ‪2000‬م رقــم اللوحــة‬\n‫(‪ )...‬وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام خامس ـ ًا‬\n‫احلكــم علــى املدعــى عليــه بحــد املســكر لقــاء اقــراره بشــرب املســكر‬\n‫سادسـ ًا احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــه تزجــره وتــردع غيــره‬\n‫لقــاء حيازتــه للمســكر بقصــد الترويــج والشــرب هــذه دعــواي وبســؤال‬\n‫املدعــى عليــه عــن الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى مــن حيازتــي‬\n‫ماوزنــه (‪ )693.7‬ســتمائة وثالثــة وتســعنب جرام ـ ًا وســبعة مــن العشــرة‬\n‫مــن اجلــرام مــن احلشــيش املخــدر ومــا عــدده (‪ )3211‬ثالثــة آالف ومائتــن‬\n‫وإحــدى عشــرة حبــة مــن حبــوب االمفيتامــن املنبــه احملظــور ومجموعــة‬\n‫كســر حبــوب مــن حبــوب االمفيتامــن املنبــه احملظــور إجمالــي وزنهــا‬\n‫(‪ )11.3‬إحــدى عشــر جرامـ ًا وثالثــة مــن العشــرة مــن اجلــرام وحبتــن مــن‬\n‫حبــوب الــروش هــذا كلــه صحيــح وقصــدي من حيــازة هــذه املضبوطات‬\n‫هــو االســتعمال الشــخصي فقــط وليــس الترويــج وكذلــك مــا جــاء يف‬\n‫الدعــوى مــن حيازتــي ثالثــة عشــر قــارورة صغيــرة حتتــوي علــى اخلمــر‬\n‫املصنــع خارجيـ ًا نــوع فــودكا فهــو صحيــح أيضـ ًا وقصــدي مــن حيازتــه‬\n‫الشــرب فقــط فأنــا أشــرب اخلمــر واســتعمل احلشــيش املخــدر وحبــوب‬\n‫االمفيتامــن احملظــور ومــا ذكــره املدعــي العــام مــن شــروعي ببيــع جــزء‬\n‫مــن احلشــيش املخــدر وبيعــي احلبــوب احملظــورة يف الســابق هــذا كلــه‬\n\n\n                                                                                        ‫‪180‬‬\n\f      ‫غيــر صحيــح وقــد مت القبــض علـ ّـي مــن قبــل مكافحــة املخــدرات يف‬\n      ‫ظهــر يــوم ‪1433/10/7‬ه ـ يف فنــدق (‪ )....‬يف الغرفــة رقــم (‪ )....‬وقــد وجــد‬\n      ‫رجــال املكافحــة يف تلــك الغرفــة احلبــوب احملظــورة واحلشــيش املخــدر‬\n      ‫وقارورتــن مــن اخلمــر كمــا وجــدوا يف ســيارتي أحــد عشــر قــارورة مــن‬\n      ‫اخلمــر وجميــع هــذه املضبوطــات تعــود لــي بقصــد االســتعمال وليــس‬\n      ‫الترويــج ولــم يســبق لــي أن قمــت ببيــع احلبــوب احملظــورة أو احلشــيش‬\n      ‫املخــدر كمــا أنــي لــم أقــم بالشــروع ببيــع احلشــيش املخــدر وأمــا رقــم‬\n      ‫اجلــوال املذكــور يف الدعــوى وهــو (‪ ) ...‬فهــو رقــم جوالــي ولــم اتفــق مــع‬\n      ‫املصــدر الســري عــن طريــق (‪ )......‬علــى بيعــه احلشــيش املخــدر هكــذا‬\n      ‫أجــاب وبســؤال املدعــي العــام البينــة علــى دعــواه قــال بينتــي مــا ذكــرت‬\n      ‫فجــرى الرجــوع إلــى اللفــات رقــم (‪ )19-17‬وتضمنــت ضبــط إفــادة‬\n      ‫املدعــى عليــه وقــد أنكــر قصــد الترويــج مــن احليــازة كمــا أنكــر بأنــه‬\n      ‫قــد أقــر لــدى الفرقــة القابضــة قيامــه بالترويــج بعــد ذلــك جــرى ســؤال‬\n      ‫املدعــي العــام عمــا ذكــره مــن وجــود ســابقة ترويــج مخــدرات للمدعــى‬\n      ‫عليــه فقــال لــم يثبــت قيامــه بالترويــج يف تلــك الســابقة وإمنــا توجهــت لــه‬\n      ‫التهمــة بالترويــج ثــم أقفلــت اجللســة الســاعة العاشــرة للتأمــل وصلــى اهلل‬\n                                                             ‫وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم الثالثــاء ‪1434/3/24‬ه ـ‬\n      ‫الســاعة احلاديــة عشــر افتتحــت اجللســة بحضــور املدعــى عليــه ‪ ..‬كمــا‬\n      ‫حضــر ‪ ..‬ســعودي بالســجل املدنــي رقــم ‪ ..‬وهــو أحــد معــدي محضــر‬\n      ‫القبــض علــى املدعــى عليــه وبســؤاله عمــا لديــه من شــهادة قال اشــهد هلل‬\n      ‫انــه توفــرت معلومــات لدينــا يف مكافحــة املخــدرات عــن قيــام املدعــى‬\n      ‫عليــه ‪ ..‬بترويــج احلشــيش املخــدر واحلبــوب احملظــورة فتــم التنســيق مــع‬\n\n\n‫‪181‬‬\n\f‫أحــد املصــادر الســرية لإلطاحــة باملدعــى عليــه متلبس ـ ًا وقــام املصــدر‬\n‫الســري بإرســال رســالة عــن طريــق (‪ ).......‬علــى جــوال املدعــى عليــه‬\n‫وهو(‪)...‬وكانــت الرســالة هــي كلمة(هتك)وهــي الرمــز املتعــارف عليــه‬\n‫عنــد املروجــن فــورد اجلــواب مــن املدعــى عليــه عــن طريــق برنامــج (‪).....‬‬\n‫علــى جــوال املصــدر بأنــه يوجــد أغــراض جديــدة وأرســل املدعــى عليــه‬\n‫صــورة مغلفــن ملــادة احلشــيش املخــدر وذكــر بــأن قيمــة الكيلــو هــو‬\n‫اثنــا عشــر ألفـ ًا وخمســمائة ريــال فأرســل املصــدر للمدعــى عليــه رســالة‬\n‫باملوافقــة علــى شــراء كيلويــن وقــد أطلعــت أنــا علــى هــذه احملادثــات‬\n‫التــي متــت عــن طريــق برنامــج (‪ )......‬وبعــد التنســيق مت ترقيــم مبلــغ اثنــا‬\n‫عشــر ألفـ ًا وخمســمائة ريــال ‪ 12500‬وتســليمها للمصــدر ومــن ثــم اجتهنا‬\n‫ملقــر اقامــة املدعــى عليــه يف فنــدق (‪ ).....‬ونظــر ًا لشــدة حــذر املدعــى‬\n‫عليــه وخوفـ ًا مــن ضيــاع املبلــغ احلكومــي فقــد مت مداهمــة املدعــى عليــه‬\n‫يف مقــر ســكنه قبــل أن يتــم بيــع احلشــيش املخــدر املتفــق عليــه ووجدنــا‬\n‫يف غرفــة املدعــى عليــه املضبوطــات مــن احلشــيش املخــدر واحلبــوب‬\n‫احملظــوره وكان عــدد احلبــوب احملظــوره كبيــر ًا كمــا وجدنــا قواريــر‬\n‫خمــر خارجــي وقــد ســمعت املدعــى عليــه يقــر بأنــه كان ينــوي البيــع‬\n‫مــن احلشــيش املخــدر واحلبــوب احملظــوره وأنــه ســبق أن بــاع احلشــيش‬\n‫املخــدر واحلبــوب احملظــوره هــذا مــا لــدي مــن شــهادة كمــا حضــر‬\n‫الشــاهد ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬وهــو أحــد معــدي محضــر‬\n‫القبــض علــى املدعــى عليــه وبســؤاله عمــا لديــه ن شــهادة قــال اشــهد هلل‬\n‫انــه توفــرت معلومــات لدينــا يف مكافحــة املخــدرات عــن قيــام املدعــى‬\n‫عليــه ‪ ..‬بترويــج احلشــيش املخــدر واحلبــوب احملظــورة فتــم التنســيق مــع‬\n‫أحــد املصــادر الســرية لإلطاحــة باملدعــى عليــه متلبس ـ ًا وقــام املصــدر‬\n\n\n                                                                                       ‫‪182‬‬\n\f      ‫الســري بإرســال رســالة عــن طريــق برنامــج (‪ ).....‬علــى جــوال املدعــى‬\n      ‫عليــه وهو(‪)..‬وكانــت الرســالة هــي كلمة(هتك)وهــي الرمــز املتعــارف‬\n      ‫عليــه عنــد املروجــن فــورد اجلــواب مــن املدعــى عليــه عــن طريــق برنامــج‬\n      ‫(‪ ).....‬علــى جــوال املصــدر بأنــه يوجــد أغــراض جديــدة وأرســل املدعــى‬\n      ‫عليــه صــورة مغلفــن ملــادة احلشــيش املخــدر وذكــر بــأن قيمــة الكيلــو‬\n      ‫هــو اثنــا عشــر ألف ـ ًا وخمســمائة ريــال فأرســل املصــدر للمدعــى عليــه‬\n      ‫رســالة باملوافقــة علــى شــراء كيلويــن وقــد أطلعــت أنــا علــى هــذه‬\n      ‫احملادثــات التــي متــت عــن طريــق برنامــج (‪ ).....‬وبعــد التنســيق مت ترقيــم‬\n      ‫مبلــغ اثنــا عشــر ألفـ ًا وخمســمائة ريــال ‪ 12500‬وتســليمها للمصــدر ومــن‬\n      ‫ثــم اجتهنــا ملقــر اقامــة املدعــى عليــه يف فنــدق (‪ ).....‬إن ونظــر ًا لشــدة‬\n      ‫حــذر املدعــى عليــه وخوفـ ًا مــن ضيــاع املبلــغ احلكومــي فقــد مت مداهمــة‬\n      ‫املدعــى عليــه يف مقــر ســكنه قبــل أن يتــم بيــع احلشــيش املخــدر املتفــق‬\n      ‫عليــه ووجدنــا يف غرفــة املدعــى عليــه املضبوطــات مــن احلشــيش املخــدر‬\n      ‫واحلبــوب احملظــوره وكان عــدد احلبــوب احملظــوره كبيــر ًا كمــا‬\n      ‫وجدنــا قواريــر خمــر خارجــي وقــد ســمعت املدعــى عليــه يقــر بأنــه كان‬\n      ‫ينــوي البيــع مــن احلشــيش املخــدر واحلبــوب احملظــوره وأنــه ســبق أن بــاع‬\n      ‫احلشــيش املخــدر واحلبــوب احملظــوره هــذا مــا لــدي مــن شــهادة ثــم قــرر‬\n      ‫كل واحــد مــن الشــاهدين بقولــه إن شــهادة بقيــة زمالئــي يف محضــر‬\n      ‫القبــض مثــل شــهادتي بالضبــط وقــد تأكــدت مــن ذلــك بنفســي هكــذا‬\n      ‫قــررا وبعــرض الشــاهدين ومــا جــاء يف شــهادتهما علــى املدعــى عليــه قــال‬\n      ‫الشــاهدين ال أعلــم عــن حالهمــا وشــهادتهما بأنــي نســقت مــع املصــدر‬\n      ‫عــن طريــق برنامــج(‪ ).....‬علــى أن أبيعــه احلشــيش واحلبــوب احملظــور وأنــي‬\n      ‫أقريــت عنــد القبــض علــي بأنــي كنــت أنــوي البيــع مــن احلشــيش املخــدر‬\n\n\n‫‪183‬‬\n\f‫واحلبــوب احملظــوره املضبوطــه بحوزتــي وأنــه ســبق أن بعــت منهــا هــذا‬\n‫كلــه غيــر صحيــح وأمــا رقــم اجلــوال املذكــور وهو(‪)...‬فهــو يعــود لــي‬\n‫ونــوع جوالــي هــو (‪ )......‬هكــذا قــرر ونظــر ًا حللــول وقــت الصــاة فقــد‬\n‫أقفلــت اجللســة عنــد الســاعة الثانيــة عشــر إال خمــس دقائــق وصلــى اهلل‬\n                                                       ‫وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــدهلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم الســبت ‪1434/3/28‬ه ـ‬\n‫الســاعة الثانيــة عشــر والنصــف افتتحــت اجللســة بحضــور املدعــى عليــه‬\n‫‪ ..‬كمــا حضــر ‪ ..‬ســعودي بالســجل املدنــي رقــم ‪ ...‬و‪ ...‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪ ...‬وجــرى تعديــل الشــاهدين ‪ ..‬و‪ ...‬التعديــل الشــرعي بعــد‬\n‫ذلــك جــرى الرجــوع إلــى اللفــة رقــم (‪ )3‬وتضمنــت محضــر التحريــز وجاء‬\n‫فيــه عــدد ووزن املضبوطــات وهــو كمــا ذكــر املدعــي العــام يف دعــواه‬\n‫كمــا جــرى الرجــوع إلــى اللفــة رقــم (‪ )48‬وتضمنــت التقريــر الكيماوي‬\n‫الشــرعي وهــو كمــا ذكــر املدعــي العــام يف دعــواه ســوى أنــه جــاء يف‬\n‫العينــة رقــم (‪/946‬ج) املتعلقــة باحلبتــان التــي يشــتبه أن تكــون روش قــد‬\n‫ثبــت بأنهمــا غيــر محظورتــان ثــم أقفلــت اجللســة الســاعة الواحــدة للتأمــل‬\n                                        ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمد هلل وحده وبعد ثم إنه يف هذا اليوم االثنني ‪1434/4/1‬هـ الساعة‬\n‫الثامنــة وعشــر دقائــق افتتحــت اجللســة بحضــور املدعــى عليــه ‪ ..‬وجــرى‬\n‫ســؤاله عــن ســابقتيه التــي ذكــر املدعــي العــام فقــال نعــم يوجــد علــي‬\n‫ســابقتني األولــى حيــازة واســتعمال مخــدرات والثانيــة حيــازة واســتعمال‬\n‫مخــدرات وتهمــة يف ترويــج املخــدرات وهــروب مــن الســلطة ومقاومــة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n                                             ‫رجــال األمــن وصــدم ســيارة فبنـ ً‬\n‫وحيــث أقــر املدعــى عليــه بحيازتــه املضبوطــات بقصــد االســتعمال‬\n\n\n                                                                                      ‫‪184‬‬\n\f      ‫كمــا أقــر بشــرب اخلمــر واســتعمال احلشــيش املخــدر واحلبــوب احملظــورة‬\n      ‫وملــا جــاء يف شــهادة الشــاهدين‪ ..‬و‪ ..‬مــن أنهمــا ســمعا املدعــى عليــه عنــد‬\n      ‫القبــض عليــه يقــر بأنــه كان ينــوي البيــع مــن احلشــيش املخــدر واحلبــوب‬\n      ‫احملظــورة وأنــه ســبق أن بــاع احلشــيش املخــدر واحلبــوب احملظــورة وهــذه‬\n      ‫الشــهادة تثبــت قصــد الترويــج مــن حيــازة احلشــيش املخــدر واحلبــوب‬\n      ‫احملظــورة كمــا أنهــا تثبــت قيــام املدعــى عليــه ببيــع احلشــيش املخــدر‬\n      ‫واحلبــوب احملظــورة فاقــرار املدعــى عليــه موجبــه التعزيــر ولــم يدفــع‬\n      ‫املدعــى عليــه باإلكــراه علــى هــذا االقــرار قــال ابــن قدامــه رحمــه اهلل‬\n      ‫تعالــى يف املغنــي(‪(()95/5‬وال يقبــل رجــوع املقــر عــن اقــراره إال فيمــا‬\n      ‫كان حــد ًا هلل تعالــى ‪،‬يــدرأ بالشــبهات ويحتــاط إلســقاطه فأمــا حقــوق‬\n      ‫اآلدميــن وحقــوق اهلل تعالــى التــي ال تــدرأ بالشــبهات كالــزكاة‬\n      ‫والكفــارات فــا يقبــل رجوعــه عنهــا وال نعلــم يف ذلــك خالفا))كمــا‬\n      ‫أن الكميــة الكبيــرة للحبــوب املضبوطــة ومــا جــاء يف الشــهادة مــن‬\n      ‫تواصــل املصــدر مــع املدعــى عليــه باجلــوال عــن طريق برنامج (‪ )....‬لشــراء‬\n      ‫احلشــيش املخــدر تؤكــد صحــة مــا جــاء يف شــهادة الشــاهدين وحيــث‬\n      ‫أنكــر املدعــى عليــه قصــد الترويــج مــن حيــازة اخلمــور وحيــث إنــه ال‬\n      ‫بينــة علــى ذلــك كمــا أنكــر الشــروع يف ترويــج احلشــيش املخــدر وال‬\n      ‫بينــة مثبتــه لذلــك وحيــث إن التهمــة متوجهــة للمدعــى عليــه بالشــروع يف‬\n      ‫ترويــج احلشــيش املخــدر وذلــك ملــا جــاء يف شــهادة الشــاهدين مــن تواصــل‬\n      ‫املصــدر الســري عــن طريــق برنامــج (‪ )......‬باجلــوال مــع رقــم اجلــوال العائد‬\n      ‫للمدعــى عليــه ألجــل االتفــاق علــى شــراء احلشــيش املخــدر وحيــث إن‬\n      ‫شــرب املســكر وحيازتــه مــن كبائــر الذنــوب فقــد لعــن رســول اهلل‬\n      ‫صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ((شــاربها وســاقيها وحاملهــا‬\n\n\n‫‪185‬‬\n\f‫واحملمولــه إليــه وعاصرهــا ومعتصرهــا وبائعهــا وآكل ثمنهــا)) واللعــن‬\n‫ال يكــون إال علــى كبيــرة مــن كبائــر الذنــوب وملــا نــص عليــه أهــل‬\n‫العلــم مــن اقامــة حــد املســكر علــى متنــاول احلشــيش املخــدر قــال ابــن‬\n‫حجــر رحمــه اهلل تعالــى يف فتــح الباري(‪(()45/10‬واســتدل مبطلــق‬\n‫قولــه صلــى اهلل عليــه وســلم((كل مســكر حرام))علــى حتــرمي مــا‬\n‫يســكر ولــو لــم يكــن شــرابا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد‬\n‫جــزم النــووي وغيــره بأنهــا مســكره))وحيث إنــه ال بينــة مثبتــه علــى‬\n‫اســتخدام املدعــى عليــه جهــاز جوالــه وســيارته يف ترويــج املخــدرات وأن‬\n‫املبلــغ املضبــوط معــه نــاجت عــن بيــع املخــدرات وحيــث إن للمدعــى عليــه‬\n‫ســابقتني يف املخــدرات وملــا جــاء يف املــواد الثامنــة والثالثــن واحلاديــة‬\n‫واألربعــن والسادســة واخلمســن والثانيــة والســتني مــن نظــام مكافحــة‬\n‫املخــدرات ‪ .‬وملــا جــاء يف محضــر التحريــز والتقرير الكيماوي الشــرعي‬\n‫والــذي أثبــت أن احلبتــن املضبوطتــن غيــر محظورتــن لــذا فقــد قــررت‬\n‫مــا يلــي أو ًال ثبــت لــدي حيــازة املدعــى عليــه مــا وزنه(‪)693.7‬ســتمائة‬\n‫وثالثــة وتســعون جرامـ ًا وســبعة بالعشــرة مــن اجلــرام مــن احلشــيش املخــدر‬\n‫بقصــد االســتعمال والترويــج ومــا عدده(‪)3211‬ثالثــة االف ومائتــان‬\n‫وأحــد عشــر حبــه مــن حبــوب االمفيتامــن املنبــه احملظــور بقصــد‬\n‫االســتعمال والترويــج ومجموعــة كســر مــن حبــوب االمفيتامــن املنبــه‬\n‫احملظــور بلــغ وزنها(‪)11.3‬أحــد عشــر جرامـ ًا وثالثــة بالعشــرة مــن اجلــرام‬\n‫بقصــد االســتعمال والترويــج كمــا ثبــت لــدي قيــام املدعــى عليــه ببيــع‬\n‫احلشــيش املخــدر واحلبــوب احملظــورة وقــررت تعزيــر املدعــى عليــه لقــاء‬\n‫مــا تقــدم بســجنه مــدة ســبع ســنوات اعتبــار ًا مــن تاريــخ إيقافــه وجلــده‬\n‫خمســمائة جلــده علــى عشــر دفعــات متســاوية بــن الدفعــة واألخــرى مــدة‬\n\n\n                                                                                    ‫‪186‬‬\n\f      ‫ال تقــل عــن عشــرة أيــام وتغرميــه مبلــغ عشــرة االف ريــال ومنعه من الســفر‬\n      ‫خــارج اململكــة مــدة ســبع ســنوات بعــد تنفيــذ عقوبــة الســجن عليــه ثانيـ ًا‬\n      ‫عــدم ثبــوت إيجابيــة احلبتــن املضبوطتــن ملــادة الــروش وعــدم ثبــوت‬\n      ‫أنهمــا محظورتــن ثالث ـ ًا عــدم ثبــوت شــروع املدعــى عليــه بترويــج جــزء‬\n      ‫مــن احلشــيش املخــدر وقــد توجهــت لــه التهمــة بذلــك وعقوبتــه التعزيريــه‬\n      ‫علــى هــذه التهمــة داخلــه يف عقوبتــه التعزيريــه املشــار لهــا بالفقــرة أو ًال‬\n      ‫رابع ـ ًا ثبــت لــدي حيــازة املدعــى عليــه ثالثــة عشــر قــارورة حتتــوي علــى‬\n      ‫خمــر خارجــي بقصــد الشــرب وعقوبتــه التعزيريــه علــى ذلــك داخلــه‬\n      ‫يف عقوبتــه التعزيريــه املشــار لهــا بالفقــرة أو ًال ولــم يثبــت لــدي قصــد‬\n      ‫الترويــج مــن هــذه احليــازة خامسـ ًا ثبــت لــدي شــرب املدعــى عليــه للخمــر‬\n      ‫واســتعماله للحشــيش املخــدر وقــررت أن يجلــد لقــاء ذلــك حــد املســكر‬\n      ‫ثمانــن جلــده دفعــه واحــده ويكــون بــن جلــد احلــد وجلــد التعزيــر مــدة‬\n      ‫ال تقــل عــن عشــرة أيــام كمــا ثبــت لــدي اســتعماله حلبــوب االمفيتامــن‬\n      ‫احملظــور وعقوبتــه التعزيريــه علــى ذلــك داخلــه يف جلــده احلــد سادس ـ ًا‬\n      ‫عــدم إجابــة املدعــي العــام فيمــا طلبــه مــن مصــادرة ســيارة املدعــى عليــه‬\n      ‫وجهــاز جوالــه وإســقاط شــريحته ومصــادرة املبلــغ املالــي املضبــوط‬\n      ‫بحوزتــه ومبــا تقــدم حكمــت وبعــرض احلكــم لــم يقنــع املدعــى عليــه‬\n      ‫مطالب ـ ًا باالســتئناف دون الئحــة اعتراضيــه كمــا أن املدعــي العــام لــم‬\n      ‫يقنــع باحلــم مكتفيـ ًا مبــا قــدم يف الئحــة دعــواه وأقفلــت اجللســة الســاعة‬\n                           ‫التاســعة إال ثلــث وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم االثنــن ‪1434/6/12‬ه ـ‬\n      ‫الســاعة الثامنــة افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية وبرفقهــا قــرار الدائــرة اجلزائيــة األولــى‬\n\n\n‫‪187‬‬\n\f‫رقــم ‪34216236‬يف ‪1434/5/19‬ه ـ املتضمــن أنــه بدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة اثبــت فضيلتــه حيــازة املدعــى عليــه‬\n‫ملــا ضبــط بحوزتــه بقصــد االســتعمال والترويــج وحكــم بعــدم إجابــة‬\n‫املدعــي العــام بعــدم مصــادرة ســيارة املدعى عليه وجهاز جواله وإســقاط‬\n‫الشــريحة ومصــادرة املبلــغ املضبــوط بحوزتــه أال يــرى فضيلتــه واحلــال مــا‬\n‫ذكــر مصــادرة مــا ذكــر لكبــر مــا وجــد مــع املدعــى عليــه ملالحظــة‬\n‫مــا ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة أ‪.‬ه ـ وأجيــب أصحــاب‬\n‫الفضيلــة وفقهــم اهلل تعالــى بــأن مصــادرة الســيارة واجلــوال تكــون عنــد‬\n‫ثبــوت اســتخدامها يف ارتــكاب اجلرميــة وكذلــك مصــادرة املبلــغ املالــي‬\n‫يكــون عنــد ثبــوت أنــه متحصــل عليــه مــن ارتــكاب اجلرميــة حســب مــا‬\n‫جــاء يف املــادة الثالثــة واخلمســون مــن نظــام مكافحــة املخــدرات وحيــث‬\n‫لــم يثبــت مــا ذكــر فإنــي الزلــت علــى مــا أجريتــه وحكمــت بــه وأقفلــت‬\n‫اجللســة الســاعة الثامنــة والربــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                                                        ‫نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم وتاريــخ‬\n‫‪1434/6/13‬ه ـ املقيــدة لــدى احملكمــة برقــم وتاريــخ ‪1434/6/20‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‬\n‫‪ ...‬املســجل برقــم ‪ 34176202‬وتاريــخ ‪1434/4/1‬ه ـ اخلــاص بدعــوى‪/‬‬\n‫املدعــي العــام ضــد‪ ...‬يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القــرار‬\n‫وصــورة ضبطــه وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n\n\n                                                                                          ‫‪188‬‬\n\f      ‫بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم يف ‪1434/5/19‬هـ قررنا‬\n      ‫املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر واهلل املوفــق وصلــى اهلل‬\n               ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/7/2‬ه ـ‬\n\n\n\n\n‫‪189‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":172,"source_page_end":189,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6b071ca89c7680dce2a1173c0b08feeb5874c18cfd9c044022d47f7fff2ab2b8","normalized_text_hash":"1fc5e1cd6cca88458bc6cfa7c6b0a3c157371187dd3242e00799480fd9c8885b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p172-34176202"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

